package com.bankfriction;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class BankFrictionPluginRunner
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(BankFrictionPlugin.class);
		RuneLite.main(args);
	}
}

package com.bankfriction;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup(BankFrictionConfig.GROUP)
public interface BankFrictionConfig extends Config
{
	String GROUP = "bankfrictionanalyser";

	@ConfigItem(
		keyName = "collectBehaviorData",
		name = "Watch bank visits",
		description = "Remember what you do at the bank to find what slows you down. It is kept in your RuneLite profile and never sent anywhere.",
		position = 0
	)
	default boolean collectBehaviorData()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showPassiveHighlights",
		name = "Light up items",
		description = "Ring the bank items of the advice, loadout or visit you click in the panel. Nothing is clicked or moved for you.",
		position = 1
	)
	default boolean showPassiveHighlights()
	{
		return true;
	}

	@Range(
		min = 20,
		max = 300
	)
	@ConfigItem(
		keyName = "maximumRetainedSessions",
		name = "Visits remembered",
		description = "How many bank visits to remember per account. More gives steadier advice; fewer reacts faster to a new layout.",
		position = 2
	)
	default int maximumRetainedSessions()
	{
		return 150;
	}
}

package com.bankfriction;

import com.bankfriction.core.Analysis;
import com.bankfriction.core.Journal;
import com.bankfriction.core.Legacy;
import com.bankfriction.core.Recorder;
import com.bankfriction.core.Report;
import com.bankfriction.overlay.BankHighlight;
import com.bankfriction.ui.FrictionPanel;
import com.bankfriction.ui.ItemIcons;
import com.bankfriction.ui.Sigil;
import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.google.inject.Provides;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ItemComposition;
import net.runelite.api.Player;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.VarClientStrChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.vars.InputType;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.AsyncBufferedImage;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@PluginDescriptor(
	name = "Bank Friction Analyser",
	description = "Finds what slows your banking down (tab hopping, searching, scrolling, misclicks) and shows what to move, gather or tag",
	tags = {"bank", "analytics", "organizer", "organiser", "loadout", "gear", "layout", "tags"}
)
public class BankFrictionPlugin extends Plugin
{
	private static final Logger log = LoggerFactory.getLogger(BankFrictionPlugin.class);
	private static final String JOURNAL_KEY = "journal";
	/** Where the first version kept every account's history together. */
	private static final String LEGACY_KEY = "snapshot";
	/** Ticks between saves while something has changed, about half a minute. */
	private static final int SAVE_TICKS = 50;
	/** Bank items are laid out on a 36 pixel grid. */
	private static final int ROW_HEIGHT = 36;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ItemManager itemManager;

	@Inject
	private Gson gson;

	@Inject
	private BankFrictionConfig config;

	private final BankHighlight highlight = new BankHighlight();

	private FrictionPanel panel;
	private NavigationButton navButton;

	private String profile;
	private Recorder recorder;
	private boolean bankOpen;
	private boolean searching;
	private boolean unsaved;
	private int ticks;
	/** Ticks until the panel is refreshed after logging in, once the player's name is known. */
	private int refreshIn = -1;

	/** The bank item being dragged, and the last place it was over. */
	private int dragItem = -1;
	private int dragIndex = -1;
	private Widget dragOver;

	@Provides
	BankFrictionConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BankFrictionConfig.class);
	}

	@Override
	protected void startUp()
	{
		ItemIcons icons = (itemId, onLoaded) ->
		{
			AsyncBufferedImage image = itemManager.getImage(itemId);
			image.onLoaded(onLoaded);
			return image;
		};
		panel = new FrictionPanel(icons, this::light, () -> clientThread.invokeLater(this::clearHistory));
		navButton = NavigationButton.builder()
			.tooltip("Bank Friction Analyser")
			.icon(Sigil.icon(16))
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		highlight.setEnabled(config.showPassiveHighlights());
		overlayManager.add(highlight);
		clientThread.invokeLater(() ->
		{
			loadProfile();
			publish();
		});
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(highlight);
		highlight.setItems(null);
		clientToolbar.removeNavigation(navButton);
		clientThread.invokeLater(() ->
		{
			closeVisit();
			save();
			recorder = null;
			profile = null;
			bankOpen = false;
			searching = false;
		});
		panel = null;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING || state == GameState.CONNECTION_LOST)
		{
			closeVisit();
			save();
			publish();
		}
		else if (state == GameState.LOGGED_IN)
		{
			refreshIn = 2;
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		closeVisit();
		save();
		loadProfile();
		publish();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!BankFrictionConfig.GROUP.equals(event.getGroup()) || event.getKey().equals(JOURNAL_KEY))
		{
			return;
		}
		highlight.setEnabled(config.showPassiveHighlights());
		clientThread.invokeLater(() ->
		{
			if (recorder != null)
			{
				recorder.setKeep(config.maximumRetainedSessions());
				if (!config.collectBehaviorData())
				{
					closeVisit();
				}
			}
			publish();
		});
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (recorder == null)
		{
			return;
		}
		ticks++;
		if (refreshIn >= 0 && refreshIn-- == 0)
		{
			publish();
		}
		long now = System.currentTimeMillis();
		boolean open = isBankOpen();
		if (open && !bankOpen)
		{
			bankOpen = true;
			if (config.collectBehaviorData())
			{
				recorder.open(now, client.getVarbitValue(VarbitID.BANK_CURRENTTAB));
			}
			publish();
		}
		else if (!open && bankOpen)
		{
			closeVisit();
			publish();
		}
		else if (open && recorder.tick(now))
		{
			unsaved = true;
			publish();
		}

		if (searching && !isSearching())
		{
			searching = false;
			recorder.endSearch(now);
		}
		if (unsaved && ticks % SAVE_TICKS == 0)
		{
			save();
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (recorder != null && bankOpen && event.getVarbitId() == VarbitID.BANK_CURRENTTAB)
		{
			recorder.tab(event.getValue(), System.currentTimeMillis());
		}
	}

	@Subscribe
	public void onVarClientStrChanged(VarClientStrChanged event)
	{
		if (recorder == null || !bankOpen || event.getIndex() != VarClientID.MESLAYERINPUT || !isSearching())
		{
			return;
		}
		// The chat box input is shared with quantity prompts, so it only counts as a search while the bank's search is open.
		searching = true;
		recorder.searchText(client.getVarcStrValue(VarClientID.MESLAYERINPUT), System.currentTimeMillis());
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (recorder == null || !recorder.isOpen())
		{
			return;
		}
		String option = event.getMenuOption();
		if (option == null)
		{
			return;
		}
		int widgetId = event.getParam1();
		long now = System.currentTimeMillis();
		if (widgetId == InterfaceID.Bankmain.ITEMS && option.startsWith("Withdraw"))
		{
			int itemId = event.getItemId();
			if (itemId <= 0)
			{
				return;
			}
			int row = -1;
			boolean deep = false;
			Widget container = client.getWidget(InterfaceID.Bankmain.ITEMS);
			Widget slot = container == null ? null : container.getChild(event.getParam0());
			if (slot != null)
			{
				row = slot.getRelativeY() / ROW_HEIGHT;
				// Below the first screen of the bank, so it had to be scrolled to.
				deep = slot.getRelativeY() + slot.getHeight() > container.getHeight();
			}
			recorder.withdraw(itemId, name(itemId), now, row, deep);
		}
		else if (widgetId == InterfaceID.Bankside.ITEMS && option.startsWith("Deposit"))
		{
			int itemId = event.getItemId();
			if (itemId > 0)
			{
				int canonical = itemManager.canonicalize(itemId);
				recorder.deposit(canonical, name(canonical), now);
			}
		}
	}

	@Subscribe
	public void onClientTick(ClientTick tick)
	{
		if (recorder == null || !recorder.isOpen())
		{
			return;
		}
		if (client.isDraggingWidget())
		{
			Widget dragged = client.getDraggedWidget();
			if (dragged != null && dragged.getId() == InterfaceID.Bankmain.ITEMS && dragged.getItemId() > 0)
			{
				dragItem = dragged.getItemId();
				dragIndex = dragged.getIndex();
				Widget over = client.getDraggedOnWidget();
				if (over != null)
				{
					dragOver = over;
				}
			}
			return;
		}
		if (dragItem > 0)
		{
			Widget over = dragOver;
			boolean moved = over != null
				&& (over.getId() == InterfaceID.Bankmain.ITEMS && over.getIndex() != dragIndex
				|| over.getId() == InterfaceID.Bankmain.TABS);
			if (moved)
			{
				recorder.rearrange(dragItem, name(dragItem), System.currentTimeMillis());
			}
			dragItem = -1;
			dragIndex = -1;
			dragOver = null;
		}
	}

	private boolean isBankOpen()
	{
		Widget items = client.getWidget(InterfaceID.Bankmain.ITEMS);
		return items != null && !items.isHidden();
	}

	private boolean isSearching()
	{
		return client.getVarcIntValue(VarClientID.MESLAYERMODE) == InputType.SEARCH.getType();
	}

	private String name(int itemId)
	{
		ItemComposition composition = itemManager.getItemComposition(itemId);
		return composition == null ? null : composition.getName();
	}

	private void closeVisit()
	{
		bankOpen = false;
		searching = false;
		dragItem = -1;
		dragOver = null;
		if (recorder != null && recorder.close(System.currentTimeMillis()))
		{
			unsaved = true;
		}
	}

	private void loadProfile()
	{
		profile = configManager.getRSProfileKey();
		recorder = null;
		if (profile == null)
		{
			return;
		}
		Journal journal = null;
		try
		{
			String saved = configManager.getRSProfileConfiguration(BankFrictionConfig.GROUP, JOURNAL_KEY);
			if (saved != null && !saved.isEmpty())
			{
				Journal read = gson.fromJson(saved, Journal.class);
				journal = read == null ? null : read.repair();
			}
		}
		catch (JsonParseException e)
		{
			log.warn("Could not read the saved bank visits, starting afresh", e);
		}
		unsaved = false;
		if (journal == null)
		{
			journal = Legacy.read(configManager.getConfiguration(BankFrictionConfig.GROUP, LEGACY_KEY));
			if (journal != null)
			{
				// The first version kept one history for every account; it moves to the first account that logs in.
				unsaved = true;
			}
		}
		if (journal == null)
		{
			journal = new Journal();
		}
		recorder = new Recorder(journal, config.maximumRetainedSessions());
		journal.trim(config.maximumRetainedSessions());
		if (unsaved)
		{
			save();
			configManager.unsetConfiguration(BankFrictionConfig.GROUP, LEGACY_KEY);
		}
	}

	private void save()
	{
		if (profile == null || recorder == null || !unsaved)
		{
			return;
		}
		unsaved = false;
		configManager.setConfiguration(BankFrictionConfig.GROUP, profile, JOURNAL_KEY, gson.toJson(recorder.getJournal()));
	}

	private void clearHistory()
	{
		if (recorder == null)
		{
			return;
		}
		Journal journal = recorder.getJournal();
		journal.getVisits().clear();
		journal.getNames().clear();
		boolean open = recorder.isOpen();
		recorder = new Recorder(journal, config.maximumRetainedSessions());
		if (open && config.collectBehaviorData())
		{
			recorder.open(System.currentTimeMillis(), client.getVarbitValue(VarbitID.BANK_CURRENTTAB));
		}
		unsaved = true;
		save();
		publish();
	}

	/** Called from the panel on the Swing thread with what to ring in the bank. */
	private void light(String title, List<Integer> items)
	{
		List<Integer> copy = new ArrayList<>(items);
		clientThread.invokeLater(() ->
		{
			// Ring an item's placeholder too, so it can be found when every one is in the inventory.
			Set<Integer> ids = new HashSet<>();
			for (int id : copy)
			{
				ids.add(id);
				ItemComposition composition = itemManager.getItemComposition(id);
				if (composition != null && composition.getPlaceholderId() > 0)
				{
					ids.add(composition.getPlaceholderId());
				}
			}
			highlight.setItems(ids);
		});
	}

	/** Works the report out on the client thread and hands it to the panel. */
	private void publish()
	{
		FrictionPanel target = panel;
		if (target == null)
		{
			return;
		}
		boolean loggedIn = client.getGameState() == GameState.LOGGED_IN;
		Report report = recorder == null ? Report.EMPTY : Analysis.of(recorder.getJournal());
		Player player = client.getLocalPlayer();
		String name = loggedIn && player != null ? player.getName() : null;
		FrictionPanel.State state = !loggedIn ? FrictionPanel.State.LOGGED_OUT
			: config.collectBehaviorData() ? FrictionPanel.State.READY : FrictionPanel.State.PAUSED;
		boolean open = bankOpen;
		long now = System.currentTimeMillis();
		SwingUtilities.invokeLater(() -> target.update(report, name, state, open, now));
	}
}

package com.bankfriction.core;

/**
 * One thing done during a bank visit. Field names are kept short because every visit is saved
 * in the RuneLite profile.
 */
public final class Action
{
	public enum Kind
	{
		/** An item taken out of the bank. */
		WITHDRAW,
		/** An item put into the bank from the inventory. */
		DEPOSIT,
		/** A different bank tab opened. */
		TAB,
		/** A finished bank search; the text is in {@link #getQuery()}. */
		SEARCH,
		/** An item dragged to a new place in the bank. */
		REARRANGE
	}

	private Kind k;
	/** The item, or 0. */
	private int i;
	/** Milliseconds after the visit began. */
	private int t;
	/** The bank row the item sat on when taken, counted from the top of the view, or -1. */
	private int r = -1;
	/** The bank tab open at the time, 0 for the main tab, or -1. */
	private int b = -1;
	/** True when the item was below the bank's first screen, so it had to be scrolled to. */
	private boolean d;
	/** True when the item was taken while a search was showing. */
	private boolean s;
	/** The search text, for searches. */
	private String q;

	public Action()
	{
	}

	private Action(Kind kind, int itemId, int time)
	{
		this.k = kind;
		this.i = itemId;
		this.t = time;
	}

	public static Action withdraw(int itemId, int time, int row, int tab, boolean deep, boolean searched)
	{
		Action a = new Action(Kind.WITHDRAW, itemId, time);
		a.r = row;
		a.b = tab;
		a.d = deep;
		a.s = searched;
		return a;
	}

	public static Action deposit(int itemId, int time)
	{
		return new Action(Kind.DEPOSIT, itemId, time);
	}

	public static Action tab(int tab, int time)
	{
		Action a = new Action(Kind.TAB, 0, time);
		a.b = tab;
		return a;
	}

	public static Action search(String query, int time)
	{
		Action a = new Action(Kind.SEARCH, 0, time);
		a.q = query;
		return a;
	}

	public static Action rearrange(int itemId, int time)
	{
		return new Action(Kind.REARRANGE, itemId, time);
	}

	public Kind getKind()
	{
		return k;
	}

	public int getItemId()
	{
		return i;
	}

	public int getTime()
	{
		return t;
	}

	public int getRow()
	{
		return r;
	}

	public int getTab()
	{
		return b;
	}

	public boolean isDeep()
	{
		return d;
	}

	public boolean isSearched()
	{
		return s;
	}

	public String getQuery()
	{
		return q == null ? "" : q;
	}
}

package com.bankfriction.core;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/** One suggestion for a bank that takes less hunting, with the evidence behind it. */
public final class Advice
{
	public enum Kind
	{
		/** A loadout spread over several tabs or far apart rows. */
		GATHER,
		/** Items you keep scrolling down for. */
		RAISE,
		/** A search you keep typing. */
		SEARCH,
		/** Items you take out and put straight back. */
		PUT_BACK,
		/** Partial potion doses taken out one by one. */
		DECANT,
		/** A loadout whose usual gear-up is far slower than your best. */
		PACE
	}

	private final Kind kind;
	private final String title;
	private final String body;
	private final List<Integer> items;
	private final double secondsPerTrip;
	private final int trips;
	private final String evidence;

	Advice(Kind kind, String title, String body, List<Integer> items, double secondsPerTrip, int trips, String evidence)
	{
		this.kind = kind;
		this.title = title;
		this.body = body;
		this.items = new ArrayList<>(items);
		this.secondsPerTrip = secondsPerTrip;
		this.trips = trips;
		this.evidence = evidence;
	}

	public Kind getKind()
	{
		return kind;
	}

	public String getTitle()
	{
		return title;
	}

	public String getBody()
	{
		return body;
	}

	/** The items to light up in the bank, most important first. */
	public List<Integer> getItems()
	{
		return Collections.unmodifiableList(items);
	}

	/** About how many seconds a trip this would save. */
	public double getSecondsPerTrip()
	{
		return secondsPerTrip;
	}

	/** How many remembered trips it applies to. */
	public int getTrips()
	{
		return trips;
	}

	/** A short line of what was seen, such as "9 of 12 trips". */
	public String getEvidence()
	{
		return evidence;
	}

	/** What it is worth over the remembered trips; advice is shown most valuable first. */
	public double impact()
	{
		return secondsPerTrip * trips;
	}

	/** A stable key, so a chosen suggestion stays chosen when the list is rebuilt. */
	public String key()
	{
		return kind + ":" + items;
	}
}

package com.bankfriction.core;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/** Reads the journal and works out the friction score, the loadouts and the advice. */
public final class Analysis
{
	/** Gear-ups averaged for the score, and again for the score before it. */
	static final int SCORE_WINDOW = 15;
	/** Fewer gear-ups than this and there is no score yet. */
	static final int MIN_TRIPS_FOR_SCORE = 3;
	/** A visit needs this many items taken out to count toward a loadout. */
	static final int MIN_LOADOUT_ITEMS = 3;
	/** A loadout must be seen this many times. */
	static final int MIN_LOADOUT_TRIPS = 3;
	/** How alike a visit must be to a loadout to join it. */
	static final double JOIN = 0.45;
	/** An item is core to a loadout when it is in this share of its trips. */
	static final double CORE = 0.6;
	/** Patterns must repeat this many times before they become advice. */
	static final int MIN_REPEATS = 3;
	/** An item counts as kept deep when this share of its withdrawals needed a scroll. */
	static final double DEEP_SHARE = 0.6;
	static final int MAX_ADVICE = 8;
	static final int MAX_LOADOUTS = 6;
	static final int RECENT = 40;
	private static final Pattern DOSE = Pattern.compile("^(.*)\\(([1-4])\\)$");

	private Analysis()
	{
	}

	public static Report of(Journal journal)
	{
		List<Visit> visits = journal.getVisits();
		List<Visit> trips = new ArrayList<>();
		double lost = 0;
		for (Visit visit : visits)
		{
			lost += visit.lostSeconds();
			if (visit.withdrawals() > 0)
			{
				trips.add(visit);
			}
		}

		int friction = -1;
		int previous = -1;
		if (trips.size() >= MIN_TRIPS_FOR_SCORE)
		{
			int end = trips.size();
			int from = Math.max(0, end - SCORE_WINDOW);
			friction = averageFriction(trips.subList(from, end));
			int prevFrom = Math.max(0, from - SCORE_WINDOW);
			if (from - prevFrom >= MIN_TRIPS_FOR_SCORE)
			{
				previous = averageFriction(trips.subList(prevFrom, from));
			}
		}

		List<Integer> gearUps = new ArrayList<>();
		for (Visit trip : trips)
		{
			gearUps.add(trip.gearUpMillis());
		}

		List<Loadout> loadouts = loadouts(journal, trips);
		List<Advice> advice = new ArrayList<>();
		gatherAdvice(journal, loadouts, trips, advice);
		raiseAdvice(journal, trips, advice);
		searchAdvice(journal, visits, advice);
		putBackAdvice(journal, visits, advice);
		decantAdvice(journal, trips, advice);
		paceAdvice(loadouts, advice);
		advice.sort((x, y) -> Double.compare(y.impact(), x.impact()));
		if (advice.size() > MAX_ADVICE)
		{
			advice = new ArrayList<>(advice.subList(0, MAX_ADVICE));
		}

		List<Visit> recent = new ArrayList<>();
		for (int i = visits.size() - 1; i >= 0 && recent.size() < RECENT; i--)
		{
			recent.add(visits.get(i));
		}
		return new Report(friction, previous, trips.size(), visits.size(), median(gearUps), lost,
			advice, loadouts, recent, journal.getNames());
	}

	private static int averageFriction(List<Visit> visits)
	{
		if (visits.isEmpty())
		{
			return -1;
		}
		double sum = 0;
		for (Visit visit : visits)
		{
			sum += visit.friction();
		}
		return (int) Math.round(sum / visits.size());
	}

	// ---- Loadouts -------------------------------------------------------------------------

	/** A loadout being built: the visits in it and how often each item appears. */
	private static final class Cluster
	{
		final List<Visit> members = new ArrayList<>();
		final Map<Integer, Integer> counts = new HashMap<>();
		/** Sum of the order each item was taken in, to put the first taken first. */
		final Map<Integer, Integer> order = new HashMap<>();

		void add(Visit visit, Set<Integer> items)
		{
			members.add(visit);
			int index = 0;
			for (int item : items)
			{
				counts.merge(item, 1, Integer::sum);
				order.merge(item, index++, Integer::sum);
			}
		}

		Set<Integer> core()
		{
			Set<Integer> core = new HashSet<>();
			int need = (int) Math.ceil(members.size() * CORE);
			for (Map.Entry<Integer, Integer> e : counts.entrySet())
			{
				if (e.getValue() >= need)
				{
					core.add(e.getKey());
				}
			}
			return core.isEmpty() ? counts.keySet() : core;
		}

		List<Integer> sortedCore()
		{
			List<Integer> core = new ArrayList<>(core());
			core.sort((a, b) ->
			{
				int byCount = Integer.compare(counts.get(b), counts.get(a));
				if (byCount != 0)
				{
					return byCount;
				}
				return Double.compare(order.get(a) / (double) counts.get(a), order.get(b) / (double) counts.get(b));
			});
			return core;
		}
	}

	static double similarity(Set<Integer> a, Set<Integer> b)
	{
		if (a.isEmpty() && b.isEmpty())
		{
			return 0;
		}
		int both = 0;
		for (int x : a)
		{
			if (b.contains(x))
			{
				both++;
			}
		}
		return both / (double) (a.size() + b.size() - both);
	}

	private static List<Loadout> loadouts(Journal journal, List<Visit> trips)
	{
		List<Cluster> clusters = new ArrayList<>();
		for (Visit trip : trips)
		{
			Set<Integer> items = trip.withdrawn();
			if (items.size() < MIN_LOADOUT_ITEMS)
			{
				continue;
			}
			Cluster best = null;
			double bestScore = JOIN;
			for (Cluster cluster : clusters)
			{
				double score = similarity(items, cluster.core());
				if (score >= bestScore)
				{
					best = cluster;
					bestScore = score;
				}
			}
			if (best == null)
			{
				best = new Cluster();
				clusters.add(best);
			}
			best.add(trip, items);
		}

		List<Loadout> loadouts = new ArrayList<>();
		for (Cluster cluster : clusters)
		{
			if (cluster.members.size() < MIN_LOADOUT_TRIPS)
			{
				continue;
			}
			List<Integer> core = cluster.sortedCore();
			if (core.size() < MIN_LOADOUT_ITEMS)
			{
				continue;
			}
			Set<Integer> coreSet = new HashSet<>(core);
			List<Integer> gearUps = new ArrayList<>();
			int best = Integer.MAX_VALUE;
			double tabSwitches = 0;
			double friction = 0;
			Set<Integer> tabs = new HashSet<>();
			Map<Integer, List<Integer>> rows = new HashMap<>();
			long lastSeen = 0;
			for (Visit visit : cluster.members)
			{
				gearUps.add(visit.gearUpMillis());
				best = Math.min(best, visit.gearUpMillis());
				tabSwitches += visit.tabSwitches();
				friction += visit.friction();
				lastSeen = Math.max(lastSeen, visit.getStart());
				for (Action action : visit.getActions())
				{
					if (action.getKind() == Action.Kind.WITHDRAW && coreSet.contains(action.getItemId()) && !action.isSearched())
					{
						if (action.getTab() >= 0)
						{
							tabs.add(action.getTab());
						}
						if (action.getRow() >= 0)
						{
							rows.computeIfAbsent(action.getItemId(), k -> new ArrayList<>()).add(action.getRow());
						}
					}
				}
			}
			int n = cluster.members.size();
			loadouts.add(new Loadout(name(journal, core), core, n, median(gearUps), best,
				tabSwitches / n, realTabs(tabs), rowSpan(rows), (int) Math.round(friction / n), lastSeen));
		}
		loadouts.sort((a, b) -> Integer.compare(b.getTrips(), a.getTrips()));
		return loadouts.size() > MAX_LOADOUTS ? new ArrayList<>(loadouts.subList(0, MAX_LOADOUTS)) : loadouts;
	}

	/** Tab 0 is the main tab, which shows every item; it only counts when nothing else was used. */
	private static int realTabs(Set<Integer> tabs)
	{
		Set<Integer> real = new HashSet<>(tabs);
		real.remove(0);
		return real.isEmpty() ? (tabs.isEmpty() ? 0 : 1) : real.size() + (tabs.contains(0) ? 1 : 0);
	}

	/** Rows between the highest and lowest item, using each item's usual row. */
	private static int rowSpan(Map<Integer, List<Integer>> rows)
	{
		if (rows.size() < 2)
		{
			return -1;
		}
		int low = Integer.MAX_VALUE;
		int high = Integer.MIN_VALUE;
		for (List<Integer> r : rows.values())
		{
			int m = median(r);
			low = Math.min(low, m);
			high = Math.max(high, m);
		}
		return high - low;
	}

	static String name(Journal journal, List<Integer> core)
	{
		String first = shortName(journal.name(core.get(0)));
		if (core.size() == 1)
		{
			return first;
		}
		return first + " & " + shortName(journal.name(core.get(1)));
	}

	private static String shortName(String name)
	{
		Matcher m = DOSE.matcher(name);
		return m.matches() ? m.group(1).trim() : name;
	}

	// ---- Advice ---------------------------------------------------------------------------

	private static void gatherAdvice(Journal journal, List<Loadout> loadouts, List<Visit> trips, List<Advice> out)
	{
		for (Loadout loadout : loadouts)
		{
			boolean spread = loadout.getTabs() >= 2 || loadout.getTabSwitches() >= 1.5;
			boolean far = loadout.getRowSpan() >= 6;
			if (!spread && !far)
			{
				continue;
			}
			String body;
			double seconds;
			if (spread)
			{
				seconds = Math.max(1, loadout.getTabSwitches()) * Visit.TAB_SECONDS;
				body = "You take these from " + plural(Math.max(2, loadout.getTabs()), "tab")
					+ " and hop tabs about " + oneDecimal(loadout.getTabSwitches()) + " times a trip."
					+ " Keeping them in one tab (a Bank Tags layout works well) lets you gear up in one view.";
			}
			else
			{
				seconds = Visit.DEEP_SECONDS;
				body = "These sit " + loadout.getRowSpan() + " rows apart. Gathering them into neighbouring rows"
					+ " means one glance instead of a scroll.";
			}
			out.add(new Advice(Advice.Kind.GATHER, "Gather the " + loadout.getName() + " loadout", body,
				loadout.getItems(), seconds, loadout.getTrips(), plural(loadout.getTrips(), "trip")));
		}
	}

	private static void raiseAdvice(Journal journal, List<Visit> visits, List<Advice> out)
	{
		Map<Integer, int[]> stats = new LinkedHashMap<>();
		Map<Integer, List<Integer>> rows = new HashMap<>();
		for (Visit trip : visits)
		{
			Set<Integer> seen = new HashSet<>();
			for (Action action : trip.getActions())
			{
				if (action.getKind() != Action.Kind.WITHDRAW || action.isSearched() || !seen.add(action.getItemId()))
				{
					continue;
				}
				int[] s = stats.computeIfAbsent(action.getItemId(), k -> new int[2]);
				s[0]++;
				if (action.isDeep())
				{
					s[1]++;
					rows.computeIfAbsent(action.getItemId(), k -> new ArrayList<>()).add(action.getRow());
				}
			}
		}
		List<Integer> deep = new ArrayList<>();
		int trips = 0;
		for (Map.Entry<Integer, int[]> e : stats.entrySet())
		{
			int[] s = e.getValue();
			if (s[0] >= MIN_REPEATS && s[1] >= s[0] * DEEP_SHARE)
			{
				deep.add(e.getKey());
				trips = Math.max(trips, s[0]);
			}
		}
		if (deep.isEmpty())
		{
			return;
		}
		deep.sort((a, b) -> Integer.compare(stats.get(b)[0], stats.get(a)[0]));
		if (deep.size() > 8)
		{
			deep = new ArrayList<>(deep.subList(0, 8));
		}
		int first = deep.get(0);
		String title;
		String body;
		if (deep.size() == 1)
		{
			int row = median(rows.get(first)) + 1;
			title = "Bring " + journal.name(first) + " up";
			body = "You have taken it out on " + plural(stats.get(first)[0], "trip") + ", and it usually sits on row "
				+ row + ", below the bank's first screen. A spot in the top rows saves the scroll every time.";
		}
		else
		{
			title = "Bring " + deep.size() + " items up";
			body = "You keep scrolling down for " + journal.name(first) + " and " + (deep.size() - 1)
				+ (deep.size() == 2 ? " other item" : " others")
				+ ". They are among your most used, yet they live below the first screen. Moving them into the top rows saves a scroll each.";
		}
		double perTrip = 0;
		for (int item : deep)
		{
			perTrip += stats.get(item)[1] / (double) Math.max(1, trips) * Visit.DEEP_SECONDS;
		}
		out.add(new Advice(Advice.Kind.RAISE, title, body, deep, perTrip, trips,
			deep.size() == 1 ? stats.get(first)[1] + " scrolls" : plural(deep.size(), "item") + " below the fold"));
	}

	private static void searchAdvice(Journal journal, List<Visit> visits, List<Advice> out)
	{
		Map<String, Integer> counts = new HashMap<>();
		Map<String, Map<Integer, Integer>> found = new HashMap<>();
		for (Visit visit : visits)
		{
			String query = null;
			for (Action action : visit.getActions())
			{
				if (action.getKind() == Action.Kind.SEARCH)
				{
					query = action.getQuery();
					counts.merge(query, 1, Integer::sum);
				}
				else if (action.getKind() == Action.Kind.WITHDRAW && action.isSearched() && query != null)
				{
					found.computeIfAbsent(query, k -> new HashMap<>()).merge(action.getItemId(), 1, Integer::sum);
				}
				else if (action.getKind() == Action.Kind.TAB)
				{
					query = null;
				}
			}
		}
		List<Map.Entry<String, Integer>> repeated = new ArrayList<>();
		for (Map.Entry<String, Integer> e : counts.entrySet())
		{
			if (e.getValue() >= MIN_REPEATS)
			{
				repeated.add(e);
			}
		}
		repeated.sort((a, b) -> Integer.compare(b.getValue(), a.getValue()));
		for (int i = 0; i < repeated.size() && i < 3; i++)
		{
			String query = repeated.get(i).getKey();
			int times = repeated.get(i).getValue();
			List<Integer> items = new ArrayList<>();
			Map<Integer, Integer> hits = found.getOrDefault(query, Collections.emptyMap());
			hits.entrySet().stream()
				.sorted((a, b) -> Integer.compare(b.getValue(), a.getValue()))
				.limit(6)
				.forEach(e -> items.add(e.getKey()));
			String body = "You have searched \"" + query + "\" " + times + " times";
			if (!items.isEmpty())
			{
				body += ", usually for " + journal.name(items.get(0));
			}
			body += ". A Bank Tags tab for it, or a home near the top, saves typing it each trip.";
			out.add(new Advice(Advice.Kind.SEARCH, "Stop searching for \"" + query + "\"", body, items,
				Visit.SEARCH_SECONDS, times, times + " searches"));
		}
	}

	private static void putBackAdvice(Journal journal, List<Visit> visits, List<Advice> out)
	{
		Map<Integer, Integer> counts = new HashMap<>();
		for (Visit visit : visits)
		{
			visit.putBacks().forEach((item, n) -> counts.merge(item, n, Integer::sum));
		}
		List<Integer> items = new ArrayList<>();
		int total = 0;
		for (Map.Entry<Integer, Integer> e : counts.entrySet())
		{
			if (e.getValue() >= MIN_REPEATS)
			{
				items.add(e.getKey());
				total += e.getValue();
			}
		}
		if (items.isEmpty())
		{
			return;
		}
		items.sort((a, b) -> Integer.compare(counts.get(b), counts.get(a)));
		int first = items.get(0);
		String body = "You took " + journal.name(first) + " out and put it straight back " + counts.get(first) + " times"
			+ (items.size() > 1 ? ", and " + (items.size() - 1) + " more item" + (items.size() > 2 ? "s" : "") + " the same way" : "")
			+ ". Something beside it probably looks alike; a gap or a different neighbour stops the misclick.";
		out.add(new Advice(Advice.Kind.PUT_BACK, items.size() == 1 ? "Stop misclicking " + journal.name(first) : "Stop the misclicks",
			body, items, Visit.PUT_BACK_SECONDS, total, total + " put back"));
	}

	private static void decantAdvice(Journal journal, List<Visit> trips, List<Advice> out)
	{
		Map<String, Integer> partial = new HashMap<>();
		Map<String, Set<Integer>> items = new HashMap<>();
		for (Visit trip : trips)
		{
			Set<String> seen = new HashSet<>();
			for (int item : trip.withdrawn())
			{
				Matcher m = DOSE.matcher(journal.name(item));
				if (!m.matches())
				{
					continue;
				}
				String base = m.group(1).trim();
				items.computeIfAbsent(base, k -> new HashSet<>()).add(item);
				if (!m.group(2).equals("4") && seen.add(base))
				{
					partial.merge(base, 1, Integer::sum);
				}
			}
		}
		List<String> bases = new ArrayList<>();
		for (Map.Entry<String, Integer> e : partial.entrySet())
		{
			if (e.getValue() >= MIN_REPEATS)
			{
				bases.add(e.getKey());
			}
		}
		if (bases.isEmpty())
		{
			return;
		}
		bases.sort((a, b) -> Integer.compare(partial.get(b), partial.get(a)));
		String base = bases.get(0);
		List<Integer> shown = new ArrayList<>(items.get(base));
		shown.sort((a, b) -> journal.name(b).compareTo(journal.name(a)));
		String body = "On " + plural(partial.get(base), "trip") + " you took out partial doses of " + base
			+ (bases.size() > 1 ? " (and " + bases.get(1) + ")" : "")
			+ ". Decanting them into full doses with Bob Barter or Zahur means one click per potion.";
		out.add(new Advice(Advice.Kind.DECANT, "Decant your " + base, body, shown,
			Visit.IDEAL_SECONDS, partial.get(base), plural(partial.get(base), "trip")));
	}

	private static void paceAdvice(List<Loadout> loadouts, List<Advice> out)
	{
		for (Loadout loadout : loadouts)
		{
			int gap = loadout.getUsualMillis() - loadout.getBestMillis();
			if (loadout.getTrips() < 4 || gap < 8_000 || loadout.getUsualMillis() < loadout.getBestMillis() * 1.6)
			{
				continue;
			}
			String body = "Your best " + loadout.getName() + " gear-up took " + seconds(loadout.getBestMillis())
				+ ", but it usually takes " + seconds(loadout.getUsualMillis())
				+ ". Light the items up from the Loadouts page and take them in the same order each time.";
			// Only part of the gap is laying out the bank; the rest is the player, so it is weighed lightly.
			out.add(new Advice(Advice.Kind.PACE, "Speed up " + loadout.getName(), body, loadout.getItems(),
				gap / 1000.0 / 3, loadout.getTrips(), "best " + seconds(loadout.getBestMillis())));
		}
	}

	// ---- Helpers --------------------------------------------------------------------------

	static int median(List<Integer> values)
	{
		if (values == null || values.isEmpty())
		{
			return 0;
		}
		List<Integer> sorted = new ArrayList<>(values);
		Collections.sort(sorted);
		int n = sorted.size();
		return n % 2 == 1 ? sorted.get(n / 2) : (sorted.get(n / 2 - 1) + sorted.get(n / 2)) / 2;
	}

	static String plural(int n, String word)
	{
		return n + " " + word + (n == 1 ? "" : "s");
	}

	private static String oneDecimal(double value)
	{
		return String.format(Locale.ROOT, "%.1f", value);
	}

	public static String seconds(int millis)
	{
		int s = (int) Math.round(millis / 1000.0);
		if (s < 60)
		{
			return s + "s";
		}
		return s / 60 + "m " + (s % 60 < 10 ? "0" : "") + s % 60 + "s";
	}
}

package com.bankfriction.core;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Every bank visit remembered for one account, oldest first, and the names of the items they
 * mention. Saved as one Gson blob in the account's RuneLite profile.
 */
public final class Journal
{
	public static final int VERSION = 2;

	private int version = VERSION;
	private final List<Visit> visits = new ArrayList<>();
	private final Map<Integer, String> names = new HashMap<>();

	public List<Visit> getVisits()
	{
		return visits;
	}

	public Map<Integer, String> getNames()
	{
		return names;
	}

	public int getVersion()
	{
		return version;
	}

	public String name(int itemId)
	{
		String name = names.get(itemId);
		return name == null || name.isEmpty() ? "Item " + itemId : name;
	}

	void add(Visit visit, int keep)
	{
		visits.add(visit);
		trim(keep);
	}

	/** Forgets the oldest visits beyond the limit, and the names nothing mentions any more. */
	public void trim(int keep)
	{
		int limit = Math.max(1, keep);
		if (visits.size() > limit)
		{
			visits.subList(0, visits.size() - limit).clear();
			Map<Integer, Boolean> used = new HashMap<>();
			for (Visit visit : visits)
			{
				for (Action action : visit.getActions())
				{
					used.put(action.getItemId(), true);
				}
			}
			names.keySet().removeIf(id -> !used.containsKey(id));
		}
	}

	/** Mends what an older or damaged save may lack. */
	public Journal repair()
	{
		visits.removeIf(v -> v == null || v.getActions().isEmpty());
		List<Visit> sorted = new ArrayList<>(visits);
		sorted.sort((x, y) -> Long.compare(x.getStart(), y.getStart()));
		visits.clear();
		visits.addAll(sorted);
		names.values().removeIf(n -> n == null);
		version = VERSION;
		return this;
	}
}

package com.bankfriction.core;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

/**
 * Reads the history saved by the first version of the plugin, which kept every account's
 * sessions together under one key, so nobody loses what was already gathered.
 */
public final class Legacy
{
	private Legacy()
	{
	}

	/** @return the old history as a journal, or null when there is nothing usable */
	public static Journal read(String saved)
	{
		if (saved == null || saved.trim().isEmpty())
		{
			return null;
		}
		try
		{
			JsonElement root = new JsonParser().parse(saved);
			if (!root.isJsonObject())
			{
				return null;
			}
			JsonObject old = root.getAsJsonObject();
			Journal journal = new Journal();
			if (old.has("itemNames") && old.get("itemNames").isJsonObject())
			{
				for (Map.Entry<String, JsonElement> e : old.getAsJsonObject("itemNames").entrySet())
				{
					try
					{
						journal.getNames().put(Integer.parseInt(e.getKey()), e.getValue().getAsString());
					}
					catch (RuntimeException ignored)
					{
						// A damaged name is not worth losing the rest for.
					}
				}
			}
			List<Visit> visits = new ArrayList<>();
			List<Long> ends = new ArrayList<>();
			for (JsonElement s : array(old, "sessions"))
			{
				JsonObject session = s.getAsJsonObject();
				long start = number(session, "startMillis");
				Visit visit = new Visit(start);
				for (JsonElement i : array(session, "interactions"))
				{
					JsonObject in = i.getAsJsonObject();
					int item = (int) number(in, "itemId");
					int t = (int) Math.max(0, number(in, "timeMillis") - start);
					String type = in.has("type") ? in.get("type").getAsString() : "";
					switch (type)
					{
						case "WITHDRAW":
							visit.add(Action.withdraw(item, t, -1, -1, false, false));
							break;
						case "DEPOSIT":
							visit.add(Action.deposit(item, t));
							break;
						case "DRAG":
							visit.add(Action.rearrange(item, t));
							break;
						case "TAB_SWITCH":
							visit.add(Action.tab(-1, t));
							break;
						default:
							break;
					}
				}
				visit.finish(number(session, "endMillis"));
				visits.add(visit);
				ends.add(Math.max(start, number(session, "endMillis")));
			}
			for (JsonElement s : array(old, "searches"))
			{
				JsonObject search = s.getAsJsonObject();
				long at = number(search, "timeMillis");
				String query = Recorder.normalize(search.has("query") ? search.get("query").getAsString() : "");
				for (int v = 0; v < visits.size() && !query.isEmpty(); v++)
				{
					Visit visit = visits.get(v);
					if (at >= visit.getStart() && at <= ends.get(v) + Recorder.IDLE_MS)
					{
						visit.add(Action.search(query, (int) (at - visit.getStart())));
						break;
					}
				}
			}
			for (Visit visit : visits)
			{
				if (!visit.isEmpty())
				{
					journal.getVisits().add(visit);
				}
			}
			journal.repair();
			return journal.getVisits().isEmpty() ? null : journal;
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	private static JsonArray array(JsonObject o, String key)
	{
		return o.has(key) && o.get(key).isJsonArray() ? o.getAsJsonArray(key) : new JsonArray();
	}

	private static long number(JsonObject o, String key)
	{
		return o.has(key) && o.get(key).isJsonPrimitive() ? o.get(key).getAsLong() : 0L;
	}
}

