/** Everything the panel shows, worked out from the journal in one go. */
public final class Report
{
	public static final Report EMPTY = new Report(-1, -1, 0, 0, 0, 0,
		Collections.emptyList(), Collections.emptyList(), Collections.emptyList(), Collections.emptyMap());

	private final int friction;
	private final int previousFriction;
	private final int trips;
	private final int visits;
	private final int usualMillis;
	private final double lostSeconds;
	private final List<Advice> advice;
	private final List<Loadout> loadouts;
	private final List<Visit> recent;
	private final Map<Integer, String> names;

	Report(int friction, int previousFriction, int trips, int visits, int usualMillis, double lostSeconds,
		List<Advice> advice, List<Loadout> loadouts, List<Visit> recent, Map<Integer, String> names)
	{
		this.friction = friction;
		this.previousFriction = previousFriction;
		this.trips = trips;
		this.visits = visits;
		this.usualMillis = usualMillis;
		this.lostSeconds = lostSeconds;
		this.advice = new ArrayList<>(advice);
		this.loadouts = new ArrayList<>(loadouts);
		this.recent = new ArrayList<>(recent);
		this.names = new HashMap<>(names);
	}

	/** Average friction of the recent gear-ups, or -1 before there are enough. */
	public int getFriction()
	{
		return friction;
	}

	/** The same over the gear-ups before those, or -1. */
	public int getPreviousFriction()
	{
		return previousFriction;
	}

	/** Visits where something was taken out. */
	public int getTrips()
	{
		return trips;
	}

	/** Every remembered visit. */
	public int getVisits()
	{
		return visits;
	}

	/** Median gear-up time, or 0. */
	public int getUsualMillis()
	{
		return usualMillis;
	}

	/** Estimated seconds lost to hunting over every remembered visit. */
	public double getLostSeconds()
	{
		return lostSeconds;
	}

	public List<Advice> getAdvice()
	{
		return Collections.unmodifiableList(advice);
	}

	public List<Loadout> getLoadouts()
	{
		return Collections.unmodifiableList(loadouts);
	}

	/** The latest visits, newest first. */
	public List<Visit> getRecent()
	{
		return Collections.unmodifiableList(recent);
	}

	public String name(int itemId)
	{
		String name = names.get(itemId);
		return name == null || name.isEmpty() ? "Item " + itemId : name;
	}
}

package com.bankfriction.core;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * One bank visit, from opening the bank to closing it, and what it cost.
 *
 * <p>Friction is an estimate of the time spent hunting rather than taking: every tab hop,
 * search, scroll below the first screen and item put straight back costs a little, and that is
 * set against the second or so a well laid out bank needs per item.
 */
public final class Visit
{
	/** Seconds a tab hop costs: the click and finding your place in the new tab. */
	public static final double TAB_SECONDS = 1.2;
	/** Seconds a search costs: opening it, typing and reading the results. */
	public static final double SEARCH_SECONDS = 4.0;
	/** Seconds a scroll below the bank's first screen costs. */
	public static final double DEEP_SECONDS = 1.8;
	/** Seconds an item taken out and put straight back costs. */
	public static final double PUT_BACK_SECONDS = 2.4;
	/** Seconds a well placed item needs: one click and a glance. */
	public static final double IDEAL_SECONDS = 1.2;
	/** An item put back within this long of taking it was a mistake, not a change of plan. */
	static final int PUT_BACK_WINDOW_MS = 15_000;
	/** No visit records more actions than this, so one long session cannot fill the profile. */
	static final int MAX_ACTIONS = 120;

	private long start;
	private int dur;
	private final List<Action> a = new ArrayList<>();

	public Visit()
	{
	}

	Visit(long start)
	{
		this.start = start;
	}

	void add(Action action)
	{
		if (a.size() < MAX_ACTIONS)
		{
			a.add(action);
		}
		dur = Math.max(dur, action.getTime());
	}

	void finish(long end)
	{
		dur = (int) Math.max(dur, Math.min(Integer.MAX_VALUE, end - start));
	}

	public long getStart()
	{
		return start;
	}

	public int getDuration()
	{
		return dur;
	}

	public List<Action> getActions()
	{
		return Collections.unmodifiableList(a);
	}

	/** True when the visit did anything worth remembering. */
	public boolean isEmpty()
	{
		return a.isEmpty();
	}

	/** Every item taken out, in the order first taken. */
	public Set<Integer> withdrawn()
	{
		Set<Integer> items = new LinkedHashSet<>();
		for (Action action : a)
		{
			if (action.getKind() == Action.Kind.WITHDRAW && action.getItemId() > 0)
			{
				items.add(action.getItemId());
			}
		}
		return items;
	}

	public int withdrawals()
	{
		return count(Action.Kind.WITHDRAW);
	}

	public int tabSwitches()
	{
		return count(Action.Kind.TAB);
	}

	public int searches()
	{
		return count(Action.Kind.SEARCH);
	}

	public int rearranges()
	{
		return count(Action.Kind.REARRANGE);
	}

	/** Items that had to be scrolled to. */
	public int deepWithdrawals()
	{
		int n = 0;
		for (Action action : a)
		{
			if (action.getKind() == Action.Kind.WITHDRAW && action.isDeep())
			{
				n++;
			}
		}
		return n;
	}

	/** The tabs items were taken from, the main tab included. */
	public Set<Integer> tabsUsed()
	{
		Set<Integer> tabs = new HashSet<>();
		for (Action action : a)
		{
			if (action.getKind() == Action.Kind.WITHDRAW && action.getTab() >= 0)
			{
				tabs.add(action.getTab());
			}
		}
		return tabs;
	}

	/** How many times each item was taken out and put straight back in. */
	public Map<Integer, Integer> putBacks()
	{
		Map<Integer, Integer> taken = new HashMap<>();
		Map<Integer, Integer> result = new HashMap<>();
		for (Action action : a)
		{
			int item = action.getItemId();
			if (item <= 0)
			{
				continue;
			}
			if (action.getKind() == Action.Kind.WITHDRAW)
			{
				taken.put(item, action.getTime());
			}
			else if (action.getKind() == Action.Kind.DEPOSIT)
			{
				Integer at = taken.remove(item);
				if (at != null && action.getTime() - at <= PUT_BACK_WINDOW_MS)
				{
					result.merge(item, 1, Integer::sum);
				}
			}
		}
		return result;
	}

	public int putBackCount()
	{
		int n = 0;
		for (int c : putBacks().values())
		{
			n += c;
		}
		return n;
	}

	/** From opening the bank to taking the last item out; the whole visit when nothing was taken. */
	public int gearUpMillis()
	{
		int last = -1;
		for (Action action : a)
		{
			if (action.getKind() == Action.Kind.WITHDRAW)
			{
				last = Math.max(last, action.getTime());
			}
		}
		return last < 0 ? dur : last;
	}

	/** Estimated seconds lost to hunting for items. */
	public double lostSeconds()
	{
		return tabSwitches() * TAB_SECONDS
			+ searches() * SEARCH_SECONDS
			+ deepWithdrawals() * DEEP_SECONDS
			+ putBackCount() * PUT_BACK_SECONDS;
	}

	/** 0 for a bank where everything was at hand, rising toward 100 as hunting outweighs taking. */
	public int friction()
	{
		double lost = lostSeconds();
		double ideal = Math.max(1, withdrawals()) * IDEAL_SECONDS;
		return (int) Math.round(100 * lost / (lost + ideal));
	}

	private int count(Action.Kind kind)
	{
		int n = 0;
		for (Action action : a)
		{
			if (action.getKind() == kind)
			{
				n++;
			}
		}
		return n;
	}
}

package com.bankfriction.overlay;

import com.bankfriction.ui.Theme;
import java.awt.BasicStroke;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.geom.RoundRectangle2D;
import java.util.Collection;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

/**
 * Rings the bank items of whatever is chosen in the panel in soft gold, so they are easy to find
 * and gather. It only draws; nothing is clicked or moved.
 */
public class BankHighlight extends WidgetItemOverlay
{
	private volatile Set<Integer> items = Collections.emptySet();
	private volatile boolean enabled = true;

	public BankHighlight()
	{
		showOnBank();
	}

	/** The items to ring, already canonical; empty to ring nothing. */
	public void setItems(Collection<Integer> ids)
	{
		items = ids == null || ids.isEmpty() ? Collections.emptySet() : new HashSet<>(ids);
	}

	public void setEnabled(boolean enabled)
	{
		this.enabled = enabled;
	}

	@Override
	public void renderItemOverlay(Graphics2D g, int itemId, WidgetItem widgetItem)
	{
		Set<Integer> lit = items;
		if (!enabled || lit.isEmpty() || !lit.contains(itemId))
		{
			return;
		}
		Rectangle bounds = widgetItem.getCanvasBounds();
		if (bounds == null)
		{
			return;
		}
		Graphics2D g2 = (Graphics2D) g.create();
		Theme.smooth(g2);
		RoundRectangle2D outer = new RoundRectangle2D.Float(bounds.x - 2, bounds.y - 2, bounds.width + 3, bounds.height + 3, 8, 8);
		RoundRectangle2D inner = new RoundRectangle2D.Float(bounds.x - 1, bounds.y - 1, bounds.width + 1, bounds.height + 1, 7, 7);
		g2.setColor(Theme.alpha(Theme.GOLD, 46));
		g2.fill(inner);
		g2.setStroke(new BasicStroke(3f));
		g2.setColor(Theme.alpha(Theme.GOLD_BRIGHT, 70));
		g2.draw(outer);
		g2.setStroke(new BasicStroke(1.2f));
		g2.setColor(Theme.GOLD_BRIGHT);
		g2.draw(inner);
		g2.dispose();
	}
}

package com.bankfriction.ui;

import java.awt.Component;
import javax.swing.Timer;

/** Eases a value toward its target on the Swing thread so rings and bars fill instead of jumping. */
final class Animator
{
	private static final int FRAME_MS = 16;
	private static final double EASE = 0.18;

	private final Component owner;
	private final Timer timer;
	private double value;
	private double target;

	Animator(Component owner)
	{
		this.owner = owner;
		this.timer = new Timer(FRAME_MS, e -> step());
	}

	double get()
	{
		return value;
	}

	void set(double newTarget, boolean animate)
	{
		target = newTarget;
		if (!animate || !owner.isShowing())
		{
			value = newTarget;
			timer.stop();
			owner.repaint();
			return;
		}
		if (!timer.isRunning())
		{
			timer.start();
		}
	}

	private void step()
	{
		value += (target - value) * EASE;
		if (Math.abs(target - value) < 0.002 || !owner.isShowing())
		{
			value = target;
			timer.stop();
		}
		owner.repaint();
	}
}

package com.bankfriction.ui;

import java.awt.Color;
import java.awt.Cursor;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.LayoutManager;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;

/**
 * A rounded, softly lit surface. Optionally clickable, with a hover lift and an
 * accent stripe down the left edge.
 */
public class Card extends JPanel
{
	private Color accent;
	private boolean hover;
	private boolean highlighted;
	private Runnable onClick;

	public Card(LayoutManager layout)
	{
		super(layout);
		setOpaque(false);
		setBorder(new EmptyBorder(8, 10, 8, 10));
	}

	public Card accent(Color color)
	{
		accent = color;
		repaint();
		return this;
	}

	/** A brighter rim for the card that matters most on screen. */
	public Card highlighted(boolean value)
	{
		highlighted = value;
		repaint();
		return this;
	}

	public Card onClick(Runnable action)
	{
		onClick = action;
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		MouseAdapter adapter = new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				hover = true;
				repaint();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				// Children forward their events here, so only clear hover when the pointer has really left.
				if (!contains(SwingUtilities.convertPoint(e.getComponent(), e.getPoint(), Card.this)))
				{
					hover = false;
					repaint();
				}
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				if (SwingUtilities.isLeftMouseButton(e) && onClick != null
					&& contains(SwingUtilities.convertPoint(e.getComponent(), e.getPoint(), Card.this)))
				{
					onClick.run();
				}
			}
		};
		addMouseListener(adapter);
		Ui.forwardMouse(this, adapter);
		return this;
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, Theme.RADIUS, Theme.RADIUS);

		Color top = hover ? Theme.CARD_HOVER : Theme.CARD_TOP;
		Color bottom = hover ? Theme.mix(Theme.CARD_HOVER, Theme.CARD, 0.5) : Theme.CARD;
		g.setPaint(new GradientPaint(0, 0, top, 0, h, bottom));
		g.fill(shape);

		if (accent != null)
		{
			g.setClip(shape);
			g.setPaint(new GradientPaint(0, 0, accent, 0, h, Theme.alpha(accent, 90)));
			g.fillRect(0, 0, 3, h);
			g.setClip(null);
		}

		Color rim = highlighted ? Theme.alpha(Theme.GOLD, 150) : hover ? Theme.alpha(Theme.GOLD, 90) : Theme.STROKE_SOFT;
		g.setColor(rim);
		g.draw(shape);

		// A one pixel sheen along the top edge, like light on vellum.
		g.setColor(Theme.alpha(Color.WHITE, hover ? 22 : 12));
		g.drawLine(Theme.RADIUS / 2, 1, w - Theme.RADIUS / 2, 1);
		g.dispose();
		super.paintComponent(graphics);
	}
}

