/** A gilt-edged button; the primary style is filled, the quiet style is just an outline. */
public class CodexButton extends JComponent
{
	private final String text;
	private final boolean primary;
	private boolean hover;
	private boolean pressed;

	public CodexButton(String text, boolean primary, Runnable action)
	{
		this.text = text;
		this.primary = primary;
		setFont(Theme.small());
		setOpaque(false);
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		FontMetrics fm = getFontMetrics(getFont());
		Dimension d = new Dimension(fm.stringWidth(text) + 20, 22);
		setPreferredSize(d);
		setMinimumSize(d);
		setMaximumSize(d);
		addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				hover = true;
				repaint();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				hover = false;
				pressed = false;
				repaint();
			}

			@Override
			public void mousePressed(MouseEvent e)
			{
				pressed = true;
				repaint();
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				boolean fire = pressed && contains(e.getPoint());
				pressed = false;
				repaint();
				if (fire)
				{
					action.run();
				}
			}
		});
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		int dy = pressed ? 1 : 0;
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f + dy, w - 1, h - 2, 8, 8);
		Color text;
		if (primary)
		{
			Color top = hover ? Theme.GOLD_BRIGHT : Theme.GOLD;
			g.setPaint(new GradientPaint(0, 0, top, 0, h, Theme.GOLD_DIM));
			g.fill(shape);
			text = Theme.INK_DEEP;
		}
		else
		{
			g.setColor(hover ? Theme.alpha(Theme.GOLD, 40) : Theme.alpha(Theme.GOLD, 14));
			g.fill(shape);
			text = hover ? Theme.GOLD_BRIGHT : Theme.GOLD;
		}
		g.setColor(Theme.alpha(Theme.GOLD, primary ? 220 : 140));
		g.draw(shape);
		g.setFont(getFont());
		FontMetrics fm = g.getFontMetrics();
		g.setColor(text);
		g.drawString(this.text, (w - fm.stringWidth(this.text)) / 2, (h + fm.getAscent()) / 2 - 2 + dy);
		g.dispose();
	}
}

package com.bankfriction.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RadialGradientPaint;
import java.awt.RenderingHints;
import java.awt.geom.Arc2D;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import java.awt.image.BufferedImage;
import javax.swing.JComponent;

/**
 * The crest at the top of the panel: the medallion with its friction ring, the score in large
 * figures with a word for it, and the trips, usual gear-up and trend underneath.
 */
public class Crest extends JComponent
{
	private static final int HEIGHT = 104;

	private final Animator ring = new Animator(this);
	private String player;
	private String status = "Log in to read your bank";
	private int score = -1;
	private int previous = -1;
	private int trips;
	private int usualMillis;

	public Crest()
	{
		setOpaque(false);
		setPreferredSize(new Dimension(10, HEIGHT));
		setMinimumSize(new Dimension(10, HEIGHT));
	}

	/**
	 * @param status a line in place of the figures underneath, or null to show them
	 * @param score friction from 0 to 100, or -1 before there is one
	 */
	public void update(String player, String status, int score, int previous, int trips, int usualMillis)
	{
		this.player = player;
		this.status = status;
		this.previous = previous;
		this.trips = trips;
		this.usualMillis = usualMillis;
		boolean animate = this.score >= 0 && score >= 0;
		this.score = score;
		ring.set(Math.max(0, score), animate);
		repaint();
	}

	/** A word for a score, so the number means something at a glance. */
	public static String grade(int score)
	{
		if (score < 0)
		{
			return "Gathering";
		}
		if (score < 25)
		{
			return "Smooth";
		}
		if (score < 45)
		{
			return "Fair";
		}
		if (score < 65)
		{
			return "Clunky";
		}
		return "Tangled";
	}

	/**
	 * Draws text at twice the size of the game's bold font by doubling every pixel, the way the
	 * game itself draws large numbers, so the figures stay crisp instead of being re-rasterised.
	 *
	 * @return the width drawn
	 */
	private static int paintLarge(Graphics2D g, String text, int x, int y, Color top, Color bottom)
	{
		Font font = Theme.title();
		FontMetrics fm = g.getFontMetrics(font);
		int w = Math.max(1, fm.stringWidth(text) + 1);
		int h = fm.getHeight() + 1;
		BufferedImage small = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
		Graphics2D sg = small.createGraphics();
		sg.setFont(font);
		sg.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
		int base = fm.getAscent();
		sg.setColor(Color.BLACK);
		sg.drawString(text, 1, base + 1);
		sg.setPaint(new GradientPaint(0, base - fm.getAscent() + 3, top, 0, base, bottom));
		sg.drawString(text, 0, base);
		sg.dispose();
		Graphics2D lg = (Graphics2D) g.create();
		lg.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
		lg.drawImage(small, x, y - 2 * fm.getAscent() + 22, w * 2, h * 2, null);
		lg.dispose();
		return w * 2;
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		g.setPaint(new GradientPaint(0, 0, Theme.mix(Theme.INK, Theme.GOLD_DIM, 0.22), 0, h, Theme.INK));
		g.fillRect(0, 0, w, h);

		Color tone = Theme.friction(score);

		// The medallion: a gilt ring with the mark inside, and the friction ring around it.
		int mx = 10;
		int my = 14;
		int md = 54;
		g.setPaint(new RadialGradientPaint(mx + md / 2f, my + md / 3f, md * 0.7f, new float[]{0, 1},
			new Color[]{Theme.mix(Theme.CARD_TOP, Theme.GOLD_DIM, 0.35), Theme.INK_DEEP}));
		g.fill(new Ellipse2D.Float(mx, my, md, md));
		g.setStroke(new BasicStroke(3f));
		g.setColor(Theme.INK_DEEP);
		g.draw(new Ellipse2D.Float(mx + 2, my + 2, md - 4, md - 4));
		double fill = ring.get() / 100.0;
		if (score >= 0 && fill > 0)
		{
			g.setStroke(new BasicStroke(3f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			g.setColor(Theme.alpha(tone, 70));
			g.setStroke(new BasicStroke(5f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			g.draw(new Arc2D.Double(mx + 2, my + 2, md - 4, md - 4, 90, -360 * fill, Arc2D.OPEN));
			g.setStroke(new BasicStroke(2.4f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			g.setColor(tone);
			g.draw(new Arc2D.Double(mx + 2, my + 2, md - 4, md - 4, 90, -360 * fill, Arc2D.OPEN));
		}
		g.setStroke(new BasicStroke(1f));
		g.setPaint(new GradientPaint(mx, my, Theme.GOLD_BRIGHT, mx, my + md, Theme.GOLD_DIM));
		g.draw(new Ellipse2D.Float(mx + 5, my + 5, md - 10, md - 10));
		Sigil.paint(g, mx + 12, my + 11, md - 24);

		int tx = mx + md + 12;
		int room = w - tx - 8;
		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		String heading = (player != null ? player + "  -  " : "") + "FRICTION";
		g.setColor(Theme.TEXT_MUTED);
		g.drawString(Ui.clip(heading, small, room), tx, 22);

		int top = 27;
		if (score >= 0)
		{
			int figureW = paintLarge(g, String.valueOf(score), tx, top, Theme.mix(tone, Color.WHITE, 0.35), tone);
			g.setFont(Theme.body());
			Ui.shadowed(g, grade(score), tx + figureW + 5, top + 18, Theme.mix(tone, Theme.TEXT, 0.25));
		}
		else
		{
			paintLarge(g, "-", tx, top, Theme.GOLD_BRIGHT, Theme.GOLD);
		}

		int cy = top + 50;
		g.setFont(Theme.small());
		if (status != null)
		{
			g.setColor(Theme.mix(Theme.TEXT_MUTED, Theme.GOLD, 0.3));
			g.drawString(Ui.clip(status, small, room), tx, cy);
		}
		else
		{
			String[] labels = {"Trips", "Gear-up", "Trend"};
			String trend = "-";
			Color trendColor = Theme.TEXT_FAINT;
			if (previous >= 0 && score >= 0)
			{
				int d = score - previous;
				trend = d == 0 ? "steady" : (d > 0 ? "+" : "") + d;
				trendColor = d < 0 ? Theme.GREEN : d > 0 ? Theme.LOSS : Theme.TEXT_MUTED;
			}
			String[] values = {String.valueOf(trips), usualMillis > 0 ? Format.seconds(usualMillis) : "-", trend};
			Color[] colors = {Theme.TEXT, Theme.TEXT, trendColor};
			int cw = room / 3;
			for (int i = 0; i < 3; i++)
			{
				int x = tx + i * cw;
				g.setColor(Theme.TEXT_FAINT);
				g.drawString(labels[i], x, cy - 11);
				Ui.shadowed(g, Ui.clip(values[i], small, cw - 4), x, cy + 1, colors[i]);
			}
		}

		// The gilt rule under the crest, with a diamond at its middle.
		int y = h - 2;
		g.setStroke(new BasicStroke(1f));
		g.setPaint(new GradientPaint(0, 0, Theme.alpha(Theme.GOLD, 0), w / 2f, 0, Theme.alpha(Theme.GOLD, 150), true));
		g.drawLine(0, y, w, y);
		Path2D diamond = new Path2D.Float();
		diamond.moveTo(w / 2f, y - 3);
		diamond.lineTo(w / 2f + 3, y);
		diamond.lineTo(w / 2f, y + 3);
		diamond.lineTo(w / 2f - 3, y);
		diamond.closePath();
		g.setColor(Theme.GOLD);
		g.fill(diamond);
		g.dispose();
	}
}

package com.bankfriction.ui;

/** How times and counts are written in the panel. */
public final class Format
{
	private Format()
	{
	}

	/** 9s, 47s, 1m 05s. */
	public static String seconds(int millis)
	{
		int s = (int) Math.round(millis / 1000.0);
		if (s < 60)
		{
			return s + "s";
		}
		return s / 60 + "m " + (s % 60 < 10 ? "0" : "") + s % 60 + "s";
	}

	/** Roughly, for totals: 40s, 12m, 3h 20m. */
	public static String duration(double seconds)
	{
		long s = Math.round(seconds);
		if (s < 60)
		{
			return s + "s";
		}
		long m = s / 60;
		if (m < 60)
		{
			return m + "m";
		}
		return m / 60 + "h " + m % 60 + "m";
	}

	/** How long ago: just now, 5m ago, 3h ago, 2d ago. */
	public static String ago(long then, long now)
	{
		long m = Math.max(0, now - then) / 60_000L;
		if (m < 1)
		{
			return "just now";
		}
		if (m < 60)
		{
			return m + "m ago";
		}
		long h = m / 60;
		if (h < 24)
		{
			return h + "h ago";
		}
		return h / 24 + "d ago";
	}

	public static String plural(int n, String word)
	{
		return n + " " + word + (n == 1 ? "" : "s");
	}
}

package com.bankfriction.ui;

import com.bankfriction.core.Advice;
import com.bankfriction.core.Loadout;
import com.bankfriction.core.Report;
import com.bankfriction.core.Visit;
import java.awt.BorderLayout;
import java.awt.CardLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Graphics;
import java.awt.GridLayout;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.function.BiConsumer;
import javax.swing.JComponent;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.ScrollPaneConstants;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.PluginPanel;

/**
 * The side panel: the crest with the friction score, then three pages. Advice is what to change
 * in the bank, most valuable first; Loadouts are the sets of items you take out together; Visits
 * is the log of recent trips to the bank. Clicking any of them lights its items up in the bank.
 */
public class FrictionPanel extends PluginPanel
{
	static final int WIDTH = 200;
	private static final String[] TABS = {"advice", "loadouts", "visits"};

	/** What the panel has to show. */
	public enum State
	{
		LOGGED_OUT,
		PAUSED,
		READY
	}

	private final ItemIcons icons;
	private final BiConsumer<String, List<Integer>> onLight;
	private final Runnable onClear;
	private final Crest crest = new Crest();
	private final Segmented tabs = new Segmented(true, "Advice", "Loadouts", "Visits");
	private final JPanel litBar = new JPanel(new BorderLayout());
	private final CardLayout cards = new CardLayout();
	private final JPanel content = new JPanel(cards);
	private final JScrollPane advice = scroller();
	private final JScrollPane loadouts = scroller();
	private final JScrollPane visits = scroller();

	private Report report = Report.EMPTY;
	private State state = State.LOGGED_OUT;
	private boolean bankOpen;
	private long now;
	private String litKey;
	private String litTitle;

	/**
	 * @param onLight told the title and items to light up in the bank, or null and nothing to clear them
	 * @param onClear asked to forget every remembered visit
	 */
	public FrictionPanel(ItemIcons icons, BiConsumer<String, List<Integer>> onLight, Runnable onClear)
	{
		super(false);
		this.icons = icons;
		this.onLight = onLight;
		this.onClear = onClear;
		setLayout(new BorderLayout());
		setBackground(Theme.INK);

		JPanel north = new JPanel(new BorderLayout());
		north.setOpaque(false);
		north.add(crest, BorderLayout.NORTH);
		JPanel under = new JPanel(new BorderLayout(0, 6));
		under.setOpaque(false);
		under.setBorder(new EmptyBorder(8, 8, 2, 8));
		under.add(tabs, BorderLayout.NORTH);
		litBar.setOpaque(false);
		under.add(litBar, BorderLayout.SOUTH);
		north.add(under, BorderLayout.SOUTH);
		add(north, BorderLayout.NORTH);

		content.setOpaque(false);
		content.add(advice, TABS[0]);
		content.add(loadouts, TABS[1]);
		content.add(visits, TABS[2]);
		add(content, BorderLayout.CENTER);

		tabs.onChange(this::showTab);
		rebuild();
	}

	private static JScrollPane scroller()
	{
		JScrollPane scroll = new JScrollPane();
		scroll.setBorder(null);
		scroll.setOpaque(false);
		scroll.getViewport().setOpaque(false);
		scroll.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.getVerticalScrollBar().setUnitIncrement(16);
		scroll.getVerticalScrollBar().setPreferredSize(new Dimension(8, 0));
		return scroll;
	}

	/** Called on the Swing thread whenever the report changes. */
	public void update(Report report, String player, State state, boolean bankOpen, long now)
	{
		this.report = report == null ? Report.EMPTY : report;
		this.state = state;
		this.bankOpen = bankOpen;
		this.now = now;
		String status = null;
		if (state == State.LOGGED_OUT)
		{
			status = this.report.getVisits() > 0 ? "Logged out, as last seen" : "Log in to read your bank";
		}
		else if (state == State.PAUSED)
		{
			status = "Paused in the plugin's settings";
		}
		else if (this.report.getFriction() < 0)
		{
			status = "Bank a few times to begin";
		}
		crest.update(player, status, this.report.getFriction(), this.report.getPreviousFriction(),
			this.report.getTrips(), this.report.getUsualMillis());
		rebuild();
	}

	/** Opens one tab, for previews and tests. */
	public void showTab(int index)
	{
		tabs.setSelected(index, false);
		cards.show(content, TABS[index]);
	}

	/** Lights something up as if it were clicked, for previews and tests. */
	public void light(String key, String title, List<Integer> items)
	{
		litKey = key;
		litTitle = title;
		onLight.accept(title, items);
		rebuild();
	}

	private void toggle(String key, String title, List<Integer> items)
	{
		if (key.equals(litKey))
		{
			clearLight();
		}
		else
		{
			light(key, title, items);
		}
	}

	private void clearLight()
	{
		litKey = null;
		litTitle = null;
		onLight.accept(null, Collections.emptyList());
		rebuild();
	}

	private void rebuild()
	{
		rebuildLitBar();
		rebuildAdvice();
		rebuildLoadouts();
		rebuildVisits();
	}

	private void rebuildLitBar()
	{
		litBar.removeAll();
		if (litKey != null)
		{
			Card bar = new Card(new BorderLayout(6, 0));
			bar.accent(Theme.GOLD);
			bar.highlighted(true);
			bar.setBorder(new EmptyBorder(5, 10, 5, 6));
			JPanel text = new JPanel(new GridLayout(2, 1));
			text.setOpaque(false);
			text.add(Ui.label(bankOpen ? "LIT IN YOUR BANK" : "OPEN YOUR BANK TO SEE IT", Theme.small(), Theme.TEXT_MUTED));
			JComponent title = Ui.label(Ui.clip(litTitle, getFontMetrics(Theme.body()), WIDTH - 70), Theme.body(), Theme.GOLD_BRIGHT);
			text.add(title);
			bar.add(text, BorderLayout.CENTER);
			JPanel button = new JPanel(new FlowLayout(FlowLayout.RIGHT, 0, 4));
			button.setOpaque(false);
			button.add(new CodexButton("Clear", false, this::clearLight));
			bar.add(button, BorderLayout.EAST);
			litBar.add(bar, BorderLayout.CENTER);
		}
		litBar.revalidate();
		litBar.repaint();
	}

	private boolean waiting(StackPanel stack)
	{
		if (report.getVisits() == 0)
		{
			if (state == State.LOGGED_OUT)
			{
				stack.add(note("The bank is closed", "Log in and bank as you normally do. Bank Friction Analyser watches each trip to the bank"
					+ " and shows where your layout slows you down: tab hopping, searching, scrolling and misclicks."));
			}
			else
			{
				stack.add(note("Watching your bank", "Bank as you normally do. After a few trips this page shows what to move,"
					+ " gather or tag, with the time each change saves. Nothing is clicked or moved for you."));
			}
			return true;
		}
		return false;
	}

	private void rebuildAdvice()
	{
		StackPanel stack = new StackPanel(8, 8);
		if (waiting(stack))
		{
			replace(advice, stack);
			return;
		}
		List<Advice> list = report.getAdvice();
		if (list.isEmpty())
		{
			stack.add(note(report.getTrips() < 6 ? "Still learning your habits" : "Nothing to fix",
				report.getTrips() < 6
					? "Advice appears once a habit repeats a few times. " + Format.plural(report.getTrips(), "gear-up") + " seen so far."
					: "Your bank is laid out well for how you use it. New advice appears here if that changes."));
			replace(advice, stack);
			return;
		}
		double total = 0;
		for (Advice a : list)
		{
			total += a.impact();
		}
		Card head = new Card(new BorderLayout(0, 4));
		head.highlighted(true);
		head.add(Ui.label(Format.plural(list.size(), "change") + " worth making", Theme.title(), Theme.GOLD_BRIGHT), BorderLayout.NORTH);
		head.add(Ui.wrapped("Together they would have saved about " + Format.duration(total) + " over your last "
			+ Format.plural(report.getTrips(), "trip") + ". Click one to light its items up in your bank.",
			Theme.small(), Theme.TEXT_MUTED, WIDTH - 30), BorderLayout.CENTER);
		stack.add(head);
		stack.add(new SectionHeader("Most time saved first"));
		for (Advice a : list)
		{
			stack.add(adviceCard(a));
		}
		replace(advice, stack);
	}

	static Color accent(Advice.Kind kind)
	{
		switch (kind)
		{
			case GATHER:
				return Theme.TEAL;
			case RAISE:
				return Theme.GOLD;
			case SEARCH:
				return Theme.VIOLET;
			case PUT_BACK:
				return Theme.EMBER;
			case DECANT:
				return Theme.GREEN;
			default:
				return new Color(150, 170, 230);
		}
	}

	static String label(Advice.Kind kind)
	{
		switch (kind)
		{
			case GATHER:
				return "GATHER";
			case RAISE:
				return "MOVE UP";
			case SEARCH:
				return "TAG IT";
			case PUT_BACK:
				return "MISCLICKS";
			case DECANT:
				return "DECANT";
			default:
				return "PACE";
		}
	}

	private Card adviceCard(Advice a)
	{
		Color accent = accent(a.getKind());
		boolean lit = a.key().equals(litKey);
		Card card = new Card(new BorderLayout(0, 5));
		card.accent(accent);
		card.highlighted(lit);

		JPanel top = new JPanel(new BorderLayout());
		top.setOpaque(false);
		top.add(Ui.label(label(a.getKind()), Theme.small(), accent), BorderLayout.WEST);
		top.add(Ui.label("~" + Format.duration(a.getSecondsPerTrip()) + " a trip", Theme.small(), Theme.TEXT_MUTED), BorderLayout.EAST);

		JPanel middle = new JPanel(new BorderLayout(0, 4));
		middle.setOpaque(false);
		middle.add(Ui.wrapped(a.getTitle(), Theme.body(), lit ? Theme.GOLD_BRIGHT : Theme.TEXT, WIDTH - 30), BorderLayout.NORTH);
		middle.add(Ui.wrapped(a.getBody(), Theme.small(), Theme.TEXT_MUTED, WIDTH - 30), BorderLayout.CENTER);
		if (!a.getItems().isEmpty())
		{
			middle.add(new IconStrip(a.getItems(), icons, 32, WIDTH - 22, 2, report::name), BorderLayout.SOUTH);
		}

		JPanel bottom = new JPanel(new BorderLayout());
		bottom.setOpaque(false);
		bottom.add(Ui.label(a.getEvidence(), Theme.small(), Theme.TEXT_FAINT), BorderLayout.WEST);
		if (!a.getItems().isEmpty())
		{
			bottom.add(Ui.label(lit ? "lit" : "light up", Theme.small(), lit ? Theme.GOLD_BRIGHT : Theme.GOLD_DIM), BorderLayout.EAST);
		}

		card.add(top, BorderLayout.NORTH);
		card.add(middle, BorderLayout.CENTER);
		card.add(bottom, BorderLayout.SOUTH);
		if (!a.getItems().isEmpty())
		{
			card.onClick(() -> toggle(a.key(), a.getTitle(), a.getItems()));
		}
		return card;
	}

	private void rebuildLoadouts()
	{
		StackPanel stack = new StackPanel(8, 8);
		if (waiting(stack))
		{
			replace(loadouts, stack);
			return;
		}
		List<Loadout> list = report.getLoadouts();
		if (list.isEmpty())
		{
			stack.add(note("No loadouts yet", "When you take out the same set of three or more items on a few trips, it shows up here"
				+ " with how long it takes you to gear up for it."));
			replace(loadouts, stack);
			return;
		}
		stack.add(new SectionHeader("Your loadouts", Format.plural(list.size(), "set")));
		for (Loadout loadout : list)
		{
			stack.add(loadoutCard(loadout));
		}
		replace(loadouts, stack);
	}

	private Card loadoutCard(Loadout loadout)
	{
		boolean lit = loadout.key().equals(litKey);
		Color tone = Theme.friction(loadout.getFriction());
		Card card = new Card(new BorderLayout(0, 6));
		card.accent(tone);
		card.highlighted(lit);

		JPanel top = new JPanel(new BorderLayout(0, 1));
		top.setOpaque(false);
		top.add(Ui.wrapped(loadout.getName(), Theme.body(), lit ? Theme.GOLD_BRIGHT : Theme.TEXT, WIDTH - 30), BorderLayout.NORTH);
		top.add(Ui.label(Format.plural(loadout.getTrips(), "trip") + "  -  " + Format.ago(loadout.getLastSeen(), now)
			+ "  -  friction " + loadout.getFriction(), Theme.small(), Theme.TEXT_FAINT), BorderLayout.CENTER);
		card.add(top, BorderLayout.NORTH);
		card.add(new IconStrip(loadout.getItems(), icons, 32, WIDTH - 22, 3, report::name), BorderLayout.CENTER);

		JPanel stats = new JPanel(new GridLayout(1, 3, 4, 0));
		stats.setOpaque(false);
		stats.add(new StatTile(Format.seconds(loadout.getUsualMillis()), "Usual", "gear-up", Theme.TEXT));
		stats.add(new StatTile(Format.seconds(loadout.getBestMillis()), "Best", "so far", Theme.GREEN));
		String tabs = loadout.getTabs() > 0 ? Format.plural(loadout.getTabs(), "tab") : "";
		stats.add(new StatTile(oneDecimal(loadout.getTabSwitches()), "Hops", tabs, loadout.getTabs() >= 2 ? Theme.EMBER : Theme.TEXT));
		card.add(stats, BorderLayout.SOUTH);
		card.onClick(() -> toggle(loadout.key(), loadout.getName(), loadout.getItems()));
		return card;
	}

	private void rebuildVisits()
	{
		StackPanel stack = new StackPanel(4, 8);
		if (waiting(stack))
		{
			replace(visits, stack);
			return;
		}
		List<Visit> list = report.getRecent();
		JPanel totals = new JPanel(new GridLayout(1, 2, 6, 0));
		totals.setOpaque(false);
		totals.add(new StatTile(String.valueOf(report.getVisits()), "Visits", Format.plural(report.getTrips(), "gear-up"), Theme.GOLD));
		totals.add(new StatTile(Format.duration(report.getLostSeconds()), "Hunting", "time lost, about", Theme.friction(report.getFriction())));
		stack.add(totals);
		stack.space(2);
		stack.add(new SectionHeader("Latest trips", "friction"));
		for (Visit visit : list)
		{
			String key = "visit:" + visit.getStart();
			List<Integer> items = new ArrayList<>(visit.withdrawn());
			String title = "Trip " + Format.ago(visit.getStart(), now);
			stack.add(new VisitRow(visit, icons, now, key.equals(litKey), () -> toggle(key, title, items)));
		}
		stack.space(6);
		JPanel clear = new JPanel(new FlowLayout(FlowLayout.CENTER, 0, 0));
		clear.setOpaque(false);
		clear.add(new CodexButton("Forget every visit", false, this::confirmClear));
		stack.add(clear);
		replace(visits, stack);
	}

	private void confirmClear()
	{
		int answer = JOptionPane.showConfirmDialog(this,
			"Forget every remembered bank visit for this account?\nThe advice starts again from nothing.",
			"Bank Friction Analyser", JOptionPane.OK_CANCEL_OPTION, JOptionPane.WARNING_MESSAGE);
		if (answer == JOptionPane.OK_OPTION)
		{
			clearLight();
			onClear.run();
		}
	}

	private static String oneDecimal(double value)
	{
		return String.format(Locale.ROOT, "%.1f", value);
	}

	static Card note(String title, String text)
	{
		Card card = new Card(new BorderLayout(0, 4));
		card.accent(Theme.GOLD_DIM);
		card.add(Ui.label(title, Theme.body(), Theme.GOLD), BorderLayout.NORTH);
		card.add(Ui.wrapped(text, Theme.small(), Theme.TEXT_MUTED, WIDTH - 30), BorderLayout.CENTER);
		return card;
	}

	private static void replace(JScrollPane scroll, JComponent view)
	{
		int position = scroll.getVerticalScrollBar().getValue();
		scroll.setViewportView(view);
		scroll.revalidate();
		SwingUtilities.invokeLater(() -> scroll.getVerticalScrollBar().setValue(position));
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		g.setColor(Theme.INK);
		g.fillRect(0, 0, getWidth(), getHeight());
	}
}

package com.bankfriction.ui;

import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import java.util.function.IntFunction;
import javax.swing.JComponent;

/**
 * Items in dark wells like bank slots, wrapped into rows. A strip with more items than it shows
 * ends in a well with the count of the rest.
 */
class IconStrip extends JComponent
{
	private static final int GAP = 4;

	private final List<Integer> items;
	private final ItemIcons icons;
	private final int well;
	private final int rows;
	private final int perRow;
	private final int shown;
	private final int more;

	/**
	 * @param well the size of each well
	 * @param width the width the strip may use
	 * @param maxRows rows to show before the rest are counted
	 * @param names gives each item's name for its tooltip, or null
	 */
	IconStrip(List<Integer> items, ItemIcons icons, int well, int width, int maxRows, IntFunction<String> names)
	{
		this.items = new ArrayList<>(items);
		this.icons = icons;
		this.well = well;
		this.perRow = Math.max(1, (width + GAP) / (well + GAP));
		int capacity = perRow * maxRows;
		if (items.size() > capacity)
		{
			shown = capacity - 1;
			more = items.size() - shown;
		}
		else
		{
			shown = items.size();
			more = 0;
		}
		int cells = shown + (more > 0 ? 1 : 0);
		this.rows = Math.max(1, (cells + perRow - 1) / perRow);
		setOpaque(false);
		Dimension d = new Dimension(width, rows * (well + GAP) - GAP);
		setPreferredSize(d);
		setMinimumSize(d);
		if (names != null)
		{
			StringBuilder tip = new StringBuilder("<html>");
			for (int i = 0; i < items.size() && i < 12; i++)
			{
				tip.append(i == 0 ? "" : "<br>").append(Ui.escape(names.apply(items.get(i))));
			}
			if (items.size() > 12)
			{
				tip.append("<br>and ").append(items.size() - 12).append(" more");
			}
			setToolTipText(tip.append("</html>").toString());
		}
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		int cells = shown + (more > 0 ? 1 : 0);
		for (int i = 0; i < cells; i++)
		{
			int x = (i % perRow) * (well + GAP);
			int y = (i / perRow) * (well + GAP);
			RoundRectangle2D shape = new RoundRectangle2D.Float(x + 0.5f, y + 0.5f, well - 1, well - 1, 7, 7);
			g.setPaint(new GradientPaint(0, y, Theme.INK_DEEP, 0, y + well, Theme.mix(Theme.INK_DEEP, Theme.CARD, 0.6)));
			g.fill(shape);
			g.setColor(Theme.STROKE_SOFT);
			g.draw(shape);
			if (i < shown)
			{
				BufferedImage icon = icons == null ? null : icons.icon(items.get(i), this::repaint);
				if (icon != null)
				{
					// Item pictures are 36 by 32; smaller wells scale them down to fit.
					double scale = Math.min(1, (well - 2) / 34.0);
					int iw = (int) Math.round(icon.getWidth() * scale);
					int ih = (int) Math.round(icon.getHeight() * scale);
					g.drawImage(icon, x + (well - iw) / 2, y + (well - ih) / 2, iw, ih, null);
				}
			}
			else
			{
				g.setFont(Theme.small());
				FontMetrics fm = g.getFontMetrics();
				String text = "+" + more;
				Ui.shadowed(g, text, x + (well - fm.stringWidth(text)) / 2, y + (well + fm.getAscent()) / 2 - 1, Theme.GOLD);
			}
		}
		g.dispose();
	}
}

