package com.bankfriction.ui;

import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Path2D;
import javax.swing.JComponent;

/** A small-caps heading with a gold diamond and a line that fades into the dark. */
public class SectionHeader extends JComponent
{
	private final String text;
	private final String trailing;

	public SectionHeader(String text)
	{
		this(text, null);
	}

	public SectionHeader(String text, String trailing)
	{
		this.text = text.toUpperCase();
		this.trailing = trailing;
		setFont(Theme.small());
		setPreferredSize(new Dimension(10, 20));
		setMinimumSize(new Dimension(10, 20));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, 20));
		setAlignmentX(LEFT_ALIGNMENT);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		g.setFont(getFont());
		paint(g, text, trailing, 0, 0, getWidth(), getHeight());
		g.dispose();
	}

	/** Draws a heading in a box; the card uses the same drawing. The font must already be set. */
	static void paint(Graphics2D g, String text, String trailing, int x, int y, int w, int h)
	{
		int mid = y + h / 2 + 2;
		Path2D diamond = new Path2D.Float();
		diamond.moveTo(x + 4, mid - 4);
		diamond.lineTo(x + 8, mid);
		diamond.lineTo(x + 4, mid + 4);
		diamond.lineTo(x, mid);
		diamond.closePath();
		g.setColor(Theme.GOLD);
		g.fill(diamond);

		FontMetrics fm = g.getFontMetrics();
		int textX = x + 13;
		int baseline = mid + fm.getAscent() / 2 - 1;
		g.setColor(Theme.GOLD);
		g.drawString(text, textX, baseline);

		int lineStart = textX + fm.stringWidth(text) + 6;
		int lineEnd = x + w;
		if (trailing != null && !trailing.isEmpty())
		{
			int tw = fm.stringWidth(trailing);
			lineEnd = x + w - tw - 6;
			g.setColor(Theme.TEXT_FAINT);
			g.drawString(trailing, x + w - tw, baseline);
		}
		if (lineEnd > lineStart)
		{
			g.setPaint(new GradientPaint(lineStart, 0, Theme.alpha(Theme.GOLD, 110), lineEnd, 0, Theme.alpha(Theme.GOLD, 0)));
			g.drawLine(lineStart, mid, lineEnd, mid);
		}
	}
}

package com.bankfriction.ui;

import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import java.util.function.IntConsumer;
import javax.swing.JComponent;

/**
 * Tabs drawn as one engraved strip: the chosen segment is lit from below by a
 * gold glow, the rest sit quietly in the ink.
 */
public class Segmented extends JComponent
{
	private final String[] labels;
	private final boolean large;
	private final Animator slide = new Animator(this);
	private int selected;
	private int hover = -1;
	private IntConsumer listener;

	public Segmented(boolean large, String... labels)
	{
		this.labels = labels;
		this.large = large;
		setFont(large ? Theme.title() : Theme.small());
		int h = large ? 28 : 22;
		setPreferredSize(new Dimension(10, h));
		setMinimumSize(new Dimension(10, h));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, h));
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		MouseAdapter mouse = new MouseAdapter()
		{
			@Override
			public void mouseMoved(MouseEvent e)
			{
				int index = indexAt(e.getX());
				if (index != hover)
				{
					hover = index;
					repaint();
				}
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				hover = -1;
				repaint();
			}

			@Override
			public void mousePressed(MouseEvent e)
			{
				setSelected(indexAt(e.getX()), true);
			}
		};
		addMouseListener(mouse);
		addMouseMotionListener(mouse);
	}

	public void onChange(IntConsumer listener)
	{
		this.listener = listener;
	}

	public int getSelected()
	{
		return selected;
	}

	public void setSelected(int index, boolean notify)
	{
		if (index < 0 || index >= labels.length)
		{
			return;
		}
		boolean changed = index != selected;
		selected = index;
		slide.set(index, true);
		repaint();
		if (changed && notify && listener != null)
		{
			listener.accept(index);
		}
	}

	private int indexAt(int x)
	{
		int w = Math.max(1, getWidth());
		return Math.max(0, Math.min(labels.length - 1, x * labels.length / w));
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		float seg = w / (float) labels.length;

		RoundRectangle2D strip = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, 8, 8);
		g.setColor(Theme.INK_DEEP);
		g.fill(strip);

		float x = (float) (slide.get() * seg);
		RoundRectangle2D lit = new RoundRectangle2D.Float(x + 2, 2, seg - 4, h - 4, 6, 6);
		g.setPaint(new GradientPaint(0, 2, Theme.CARD_TOP, 0, h, Theme.mix(Theme.CARD_TOP, Theme.GOLD_DIM, 0.35)));
		g.fill(lit);
		g.setColor(Theme.alpha(Theme.GOLD, 120));
		g.draw(lit);
		g.setColor(Theme.GOLD_BRIGHT);
		g.fillRect(Math.round(x + seg * 0.3f), h - 4, Math.round(seg * 0.4f), 1);

		g.setFont(getFont());
		FontMetrics fm = g.getFontMetrics();
		for (int i = 0; i < labels.length; i++)
		{
			int tx = Math.round(i * seg + (seg - fm.stringWidth(labels[i])) / 2);
			int ty = (h + fm.getAscent()) / 2 - (large ? 2 : 1);
			java.awt.Color color = i == selected ? Theme.GOLD_BRIGHT : i == hover ? Theme.TEXT : Theme.TEXT_MUTED;
			Ui.shadowed(g, labels[i], tx, ty, color);
		}
		g.setColor(Theme.STROKE_SOFT);
		g.draw(strip);
		g.dispose();
	}
}

package com.bankfriction.ui;

import java.awt.BasicStroke;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;

/** The plugin's mark: a gilt bank chest with a teal line sweeping cleanly over its lid. */
public final class Sigil
{
	private Sigil()
	{
	}

	public static BufferedImage icon(int size)
	{
		BufferedImage image = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		Theme.smooth(g);
		paint(g, 0, 0, size);
		g.dispose();
		return image;
	}

	/** Draws the mark in a size by size box. */
	public static void paint(Graphics2D g, float x, float y, float size)
	{
		float s = size / 16f;
		float stroke = Math.max(0.7f, 0.6f * s);

		// The chest's body.
		RoundRectangle2D body = new RoundRectangle2D.Float(x + 1.6f * s, y + 7.4f * s, 12.8f * s, 7.4f * s, 2f * s, 2f * s);
		g.setPaint(new GradientPaint(x, y + 7.4f * s, Theme.GOLD, x, y + 14.8f * s, Theme.GOLD_DIM));
		g.fill(body);

		// Its arched lid.
		Path2D lid = new Path2D.Float();
		lid.moveTo(x + 1.6f * s, y + 7.4f * s);
		lid.lineTo(x + 1.6f * s, y + 6.2f * s);
		lid.curveTo(x + 1.6f * s, y + 3.2f * s, x + 14.4f * s, y + 3.2f * s, x + 14.4f * s, y + 6.2f * s);
		lid.lineTo(x + 14.4f * s, y + 7.4f * s);
		lid.closePath();
		g.setPaint(new GradientPaint(x, y + 3.6f * s, Theme.GOLD_BRIGHT, x, y + 7.4f * s, Theme.GOLD));
		g.fill(lid);

		g.setStroke(new BasicStroke(stroke));
		g.setColor(Theme.INK_DEEP);
		g.draw(body);
		g.draw(lid);

		// Iron bands and the lock plate.
		g.setColor(Theme.alpha(Theme.INK_DEEP, 200));
		g.fill(new RoundRectangle2D.Float(x + 4.2f * s, y + 4.4f * s, 1.3f * s, 10.4f * s, s, s));
		g.fill(new RoundRectangle2D.Float(x + 10.5f * s, y + 4.4f * s, 1.3f * s, 10.4f * s, s, s));
		RoundRectangle2D plate = new RoundRectangle2D.Float(x + 6.4f * s, y + 6.6f * s, 3.2f * s, 3.6f * s, 1.2f * s, 1.2f * s);
		g.setColor(Theme.INK_DEEP);
		g.fill(plate);
		g.setColor(Theme.TEAL);
		g.fill(new Ellipse2D.Float(x + 7.4f * s, y + 7.4f * s, 1.2f * s, 1.2f * s));
		g.fillRect(Math.round(x + 7.75f * s), Math.round(y + 8.2f * s), Math.max(1, Math.round(0.5f * s)), Math.max(1, Math.round(1.2f * s)));

		// The sweep: a smooth line lifting off the lid to a bright point.
		Path2D sweep = new Path2D.Float();
		sweep.moveTo(x + 0.6f * s, y + 5.2f * s);
		sweep.curveTo(x + 4.5f * s, y + 0.6f * s, x + 10f * s, y + 3.4f * s, x + 14.4f * s, y + 0.9f * s);
		g.setStroke(new BasicStroke(Math.max(2.2f, 2.4f * s), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(Theme.INK_DEEP);
		g.draw(sweep);
		g.setStroke(new BasicStroke(Math.max(1.1f, 1.3f * s), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(Theme.TEAL);
		g.draw(sweep);
		float r = 1.6f * s;
		g.setColor(Theme.alpha(Theme.TEAL, 90));
		g.fill(new Ellipse2D.Float(x + 14.4f * s - r * 1.7f, y + 0.9f * s - r * 1.7f, r * 3.4f, r * 3.4f));
		g.setColor(Theme.mix(Theme.TEAL, Theme.TEXT, 0.5));
		g.fill(new Ellipse2D.Float(x + 14.4f * s - r, y + 0.9f * s - r, r * 2, r * 2));
	}
}

package com.bankfriction.ui;

import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.Insets;
import java.awt.LayoutManager;
import java.awt.Rectangle;
import javax.swing.JPanel;
import javax.swing.Scrollable;
import javax.swing.border.EmptyBorder;

/**
 * A vertical stack where every child spans the full width at its preferred height.
 * It tracks the viewport width so nothing ever scrolls sideways in the side panel.
 */
public class StackPanel extends JPanel implements Scrollable
{
	public StackPanel(int gap, int pad)
	{
		super(new StackLayout(gap));
		setOpaque(false);
		setBorder(new EmptyBorder(pad, pad, pad, pad));
	}

	public StackPanel space(int height)
	{
		JPanel spacer = new JPanel();
		spacer.setOpaque(false);
		spacer.setPreferredSize(new Dimension(1, height));
		add(spacer);
		return this;
	}

	@Override
	public Dimension getPreferredScrollableViewportSize()
	{
		return getPreferredSize();
	}

	@Override
	public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction)
	{
		return 16;
	}

	@Override
	public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction)
	{
		return Math.max(16, visibleRect.height - 32);
	}

	@Override
	public boolean getScrollableTracksViewportWidth()
	{
		return true;
	}

	@Override
	public boolean getScrollableTracksViewportHeight()
	{
		return false;
	}

	static final class StackLayout implements LayoutManager
	{
		private final int gap;

		StackLayout(int gap)
		{
			this.gap = gap;
		}

		@Override
		public void addLayoutComponent(String name, Component comp)
		{
		}

		@Override
		public void removeLayoutComponent(Component comp)
		{
		}

		@Override
		public Dimension preferredLayoutSize(Container parent)
		{
			Insets in = parent.getInsets();
			int width = 0;
			int height = 0;
			int visible = 0;
			for (Component c : parent.getComponents())
			{
				if (!c.isVisible())
				{
					continue;
				}
				Dimension d = c.getPreferredSize();
				width = Math.max(width, d.width);
				height += d.height;
				visible++;
			}
			height += Math.max(0, visible - 1) * gap;
			return new Dimension(width + in.left + in.right, height + in.top + in.bottom);
		}

		@Override
		public Dimension minimumLayoutSize(Container parent)
		{
			return preferredLayoutSize(parent);
		}

		@Override
		public void layoutContainer(Container parent)
		{
			Insets in = parent.getInsets();
			int width = parent.getWidth() - in.left - in.right;
			int y = in.top;
			for (Component c : parent.getComponents())
			{
				if (!c.isVisible())
				{
					continue;
				}
				int h = c.getPreferredSize().height;
				c.setBounds(in.left, y, width, h);
				y += h + gap;
			}
		}
	}
}

package com.bankfriction.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JComponent;

/** A small engraved tablet: a big number, its label, and a quiet line of context. */
class StatTile extends JComponent
{
	private final String value;
	private final String label;
	private final String note;
	private final Color color;

	StatTile(String value, String label, String note, Color color)
	{
		this.value = value;
		this.label = label;
		this.note = note;
		this.color = color;
		setPreferredSize(new Dimension(10, 54));
		setOpaque(false);
		setToolTipText(note == null || note.isEmpty() ? label : label + ": " + note);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		paint(g, value, label, note, color, 0, 0, getWidth(), getHeight());
		g.dispose();
	}

	/** Draws a tablet in a box; the card uses the same drawing. */
	static void paint(Graphics2D g, String value, String label, String note, Color color, int x, int y, int w, int h)
	{
		RoundRectangle2D shape = new RoundRectangle2D.Float(x + 0.5f, y + 0.5f, w - 1, h - 1, Theme.RADIUS, Theme.RADIUS);
		g.setPaint(new GradientPaint(x, y, Theme.CARD_TOP, x, y + h, Theme.CARD));
		g.fill(shape);
		g.setColor(Theme.STROKE_SOFT);
		g.draw(shape);
		g.setColor(Theme.alpha(color, 160));
		g.fillRect(x + Theme.RADIUS, y + 1, w - Theme.RADIUS * 2, 1);

		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		g.setColor(Theme.TEXT_MUTED);
		g.drawString(label.toUpperCase(), x + 8, y + 6 + small.getAscent());

		g.setFont(Theme.title());
		FontMetrics bold = g.getFontMetrics();
		Ui.shadowed(g, Ui.clip(value, bold, w - 16), x + 8, y + 8 + small.getHeight() + bold.getAscent(), color);
		if (note != null && !note.isEmpty())
		{
			g.setFont(Theme.small());
			g.setColor(Theme.TEXT_FAINT);
			g.drawString(Ui.clip(note, small, w - 16), x + 8, y + h - 6);
		}
	}
}

package com.bankfriction.ui;

import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import net.runelite.client.ui.FontManager;

/**
 * The Codex look: warm ink, aged gold and a single arcane teal, drawn with the
 * game's own fonts so the panel reads as part of Gielinor rather than a web page.
 * Friction reads like a fever: green when the bank is smooth, gold, then ember, then blood.
 */
public final class Theme
{
	public static final Color INK = new Color(23, 20, 16);
	public static final Color INK_DEEP = new Color(16, 14, 11);
	public static final Color CARD = new Color(34, 30, 24);
	public static final Color CARD_TOP = new Color(42, 37, 29);
	public static final Color CARD_HOVER = new Color(48, 42, 33);
	public static final Color STROKE = new Color(66, 56, 42);
	public static final Color STROKE_SOFT = new Color(48, 41, 32);

	public static final Color GOLD = new Color(214, 178, 106);
	public static final Color GOLD_BRIGHT = new Color(246, 214, 144);
	public static final Color GOLD_DIM = new Color(132, 108, 66);
	public static final Color TEAL = new Color(96, 184, 170);
	public static final Color GREEN = new Color(130, 196, 108);
	public static final Color EMBER = new Color(222, 134, 86);
	public static final Color BLOCKED = new Color(176, 92, 84);
	public static final Color BLOOD = new Color(204, 70, 60);
	public static final Color BLOOD_DEEP = new Color(120, 32, 28);
	public static final Color VIOLET = new Color(176, 132, 222);

	public static final Color TEXT = new Color(234, 224, 202);
	public static final Color TEXT_MUTED = new Color(160, 148, 126);
	public static final Color TEXT_FAINT = new Color(110, 100, 84);

	public static final int RADIUS = 10;
	public static final int GUTTER = 8;

	private Theme()
	{
	}

	public static Font title()
	{
		return FontManager.getRunescapeBoldFont();
	}

	public static Font body()
	{
		return FontManager.getRunescapeFont();
	}

	public static Font small()
	{
		return FontManager.getRunescapeSmallFont();
	}

	public static Color alpha(Color c, int alpha)
	{
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), alpha);
	}

	public static Color mix(Color a, Color b, double t)
	{
		t = Math.max(0, Math.min(1, t));
		return new Color(
			(int) Math.round(a.getRed() + (b.getRed() - a.getRed()) * t),
			(int) Math.round(a.getGreen() + (b.getGreen() - a.getGreen()) * t),
			(int) Math.round(a.getBlue() + (b.getBlue() - a.getBlue()) * t),
			(int) Math.round(a.getAlpha() + (b.getAlpha() - a.getAlpha()) * t));
	}

	/** Progress colour: ember when just begun, gold through the middle, green when nearly there. */
	public static Color progressColor(double progress)
	{
		if (progress >= 1)
		{
			return GREEN;
		}
		if (progress < 0.5)
		{
			return mix(EMBER, GOLD, progress * 2);
		}
		return mix(GOLD, TEAL, (progress - 0.5) * 2);
	}

	/** A friction score's colour: green when the bank is smooth, through gold and ember to blood. */
	public static Color friction(int score)
	{
		if (score < 0)
		{
			return TEXT_MUTED;
		}
		if (score < 25)
		{
			return GREEN;
		}
		if (score < 45)
		{
			return GOLD;
		}
		if (score < 65)
		{
			return EMBER;
		}
		return LOSS;
	}

	public static final Color LOSS = new Color(214, 92, 78);

	/** Smooth shapes, but the pixel fonts stay crisp. */
	public static void smooth(Graphics2D g)
	{
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
	}
}

package com.bankfriction.ui;

import java.awt.Color;
import java.awt.Component;
import java.awt.Container;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import javax.swing.JLabel;

/** Small helpers shared by the panel's components. */
public final class Ui
{
	private Ui()
	{
	}

	public static JLabel label(String text, Font font, Color color)
	{
		JLabel label = new JLabel(text);
		label.setFont(font);
		label.setForeground(color);
		return label;
	}

	/**
	 * A label that wraps inside the side panel's narrow width. Swing's HTML renderer
	 * treats CSS pixels as points, so the width is converted to keep it in screen pixels.
	 */
	public static JLabel wrapped(String text, Font font, Color color, int width)
	{
		int css = Math.round(width * 0.75f);
		return label("<html><div style='width:" + css + "px'>" + escape(text) + "</div></html>", font, color);
	}

	public static String escape(String text)
	{
		return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	/** Lets a clickable card keep its hover and click while the pointer is over its children. */
	static void forwardMouse(Container root, MouseAdapter adapter)
	{
		for (Component child : root.getComponents())
		{
			child.addMouseListener(adapter);
			if (child instanceof Container)
			{
				forwardMouse((Container) child, adapter);
			}
		}
	}

	/** Text with the one pixel black shadow the game puts under its own lettering. */
	public static void shadowed(Graphics2D g, String text, int x, int y, Color color)
	{
		g.setColor(Color.BLACK);
		g.drawString(text, x + 1, y + 1);
		g.setColor(color);
		g.drawString(text, x, y);
	}

	/** Cuts text to fit a width, ending it with an ellipsis. */
	public static String clip(String text, java.awt.FontMetrics fm, int width)
	{
		if (text == null)
		{
			return "";
		}
		if (fm.stringWidth(text) <= width)
		{
			return text;
		}
		int end = text.length();
		while (end > 0 && fm.stringWidth(text.substring(0, end) + "...") > width)
		{
			end--;
		}
		return text.substring(0, end) + "...";
	}
}

package com.bankfriction.ui;

import com.bankfriction.core.Visit;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import javax.swing.JComponent;
import javax.swing.SwingUtilities;

/**
 * One bank visit in the log: when it was and how long the gear-up took, the first items taken,
 * what slowed it down, and its friction as a coloured pill.
 */
class VisitRow extends JComponent
{
	private static final int HEIGHT = 46;
	private static final int ICON = 20;

	private final Visit visit;
	private final List<Integer> items;
	private final ItemIcons icons;
	private final long now;
	private boolean hover;
	private boolean selected;

	VisitRow(Visit visit, ItemIcons icons, long now, boolean selected, Runnable onClick)
	{
		this.visit = visit;
		this.items = new ArrayList<>(visit.withdrawn());
		this.icons = icons;
		this.now = now;
		this.selected = selected;
		setOpaque(false);
		setPreferredSize(new Dimension(10, HEIGHT));
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		setToolTipText(tip());
		addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				hover = true;
				repaint();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				hover = false;
				repaint();
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				if (SwingUtilities.isLeftMouseButton(e) && contains(e.getPoint()))
				{
					onClick.run();
				}
			}
		});
	}

	private String tip()
	{
		return "<html>Friction " + visit.friction() + ", about " + Format.duration(visit.lostSeconds()) + " spent hunting"
			+ "<br>" + Format.plural(visit.withdrawals(), "item") + " taken, " + Format.plural(visit.tabSwitches(), "tab hop")
			+ ", " + visit.searches() + (visit.searches() == 1 ? " search" : " searches")
			+ "<br>" + Format.plural(visit.deepWithdrawals(), "scroll") + ", " + visit.putBackCount() + " put back"
			+ "<br>Click to light its items up in your bank</html>";
	}

	/** What slowed the visit down, shortest first. */
	private String notes()
	{
		List<String> parts = new ArrayList<>();
		if (visit.tabSwitches() > 0)
		{
			parts.add(Format.plural(visit.tabSwitches(), "hop"));
		}
		if (visit.searches() > 0)
		{
			parts.add(visit.searches() + (visit.searches() == 1 ? " search" : " searches"));
		}
		if (visit.putBackCount() > 0)
		{
			parts.add(visit.putBackCount() + " put back");
		}
		if (visit.deepWithdrawals() > 0)
		{
			parts.add(Format.plural(visit.deepWithdrawals(), "scroll"));
		}
		if (parts.isEmpty())
		{
			return visit.withdrawals() == 0 ? "only deposits" : "clean";
		}
		return String.join("  ", parts);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight() - 2;
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, Theme.RADIUS, Theme.RADIUS);
		Color top = hover ? Theme.CARD_HOVER : Theme.CARD_TOP;
		g.setPaint(new GradientPaint(0, 0, top, 0, h, Theme.CARD));
		g.fill(shape);
		g.setColor(selected ? Theme.alpha(Theme.GOLD, 150) : hover ? Theme.alpha(Theme.GOLD, 90) : Theme.STROKE_SOFT);
		g.draw(shape);

		int friction = visit.friction();
		Color tone = visit.withdrawals() == 0 ? Theme.TEXT_FAINT : Theme.friction(friction);

		// The friction pill on the right.
		g.setFont(Theme.body());
		FontMetrics body = g.getFontMetrics();
		String score = visit.withdrawals() == 0 ? "-" : String.valueOf(friction);
		int pw = Math.max(26, body.stringWidth(score) + 12);
		int px = w - pw - 8;
		int py = 8;
		RoundRectangle2D pill = new RoundRectangle2D.Float(px, py, pw, 18, 18, 18);
		g.setColor(Theme.alpha(tone, 40));
		g.fill(pill);
		g.setColor(Theme.alpha(tone, 160));
		g.draw(pill);
		Ui.shadowed(g, score, px + (pw - body.stringWidth(score)) / 2, py + 14, Theme.mix(tone, Theme.TEXT, 0.2));

		// When, and how long the gear-up took.
		int x = 10;
		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		String when = Format.ago(visit.getStart(), now);
		g.setColor(Theme.TEXT_FAINT);
		g.drawString(when, x, 15);
		g.setFont(Theme.body());
		String took = Format.seconds(visit.gearUpMillis());
		int tw = Math.max(small.stringWidth("00m ago"), body.stringWidth(took));
		Ui.shadowed(g, took, x, 32, Theme.TEXT);

		// The first items taken, small.
		int ix = x + tw + 10;
		int room = px - ix - 6;
		int fit = Math.max(0, (room + 2) / (ICON + 2));
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		for (int i = 0; i < items.size() && i < fit; i++)
		{
			BufferedImage icon = icons == null ? null : icons.icon(items.get(i), this::repaint);
			if (icon != null)
			{
				int iw = icon.getWidth() * ICON / 34;
				int ih = icon.getHeight() * ICON / 34;
				g.drawImage(icon, ix + i * (ICON + 2) + (ICON - iw) / 2, 5 + (ICON - ih) / 2, iw, ih, null);
			}
		}
		g.setFont(Theme.small());
		g.setColor(Theme.TEXT_MUTED);
		g.drawString(Ui.clip(notes(), small, w - ix - 8), ix, 37);
		g.dispose();
	}
}

package com.bankfriction.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;

public class AnalysisTest
{
	private static final int WHIP = 4151;
	private static final int DEFENDER = 12954;
	private static final int FIRE_CAPE = 6570;
	private static final int SHARK = 385;
	private static final int PRAYER_4 = 2434;
	private static final int PRAYER_3 = 139;
	private static final int RUNE_POUCH = 12791;

	private final Journal journal = new Journal();
	private final Recorder recorder = new Recorder(journal, 100);
	private long now = 1_700_000_000_000L;

	private void take(int item, String name, int tab, int row, boolean deep)
	{
		now += 1200;
		recorder.withdraw(item, name, now, row, deep);
	}

	/** A melee trip: three gear pieces from tab 1 and sharks from tab 2. */
	private void meleeTrip(boolean hop)
	{
		recorder.open(now, 1);
		take(WHIP, "Abyssal whip", 1, 0, false);
		take(DEFENDER, "Avernic defender", 1, 0, false);
		take(FIRE_CAPE, "Fire cape", 1, 1, false);
		if (hop)
		{
			now += 800;
			recorder.tab(2, now);
		}
		take(SHARK, "Shark", 2, 9, true);
		now += 3000;
		recorder.close(now);
		now += 600_000;
	}

	@Test
	public void recorderDropsVisitsWhereNothingHappened()
	{
		recorder.open(now, 0);
		assertFalse(recorder.close(now + 5000));
		assertTrue(journal.getVisits().isEmpty());
	}

	@Test
	public void recorderCountsTabHopsButNotTheOpeningTab()
	{
		meleeTrip(true);
		Visit visit = journal.getVisits().get(0);
		assertEquals(1, visit.tabSwitches());
		assertEquals(4, visit.withdrawals());
		assertEquals(1, visit.deepWithdrawals());
	}

	@Test
	public void searchIsCountedOnceAndMarksWhatItFound()
	{
		recorder.open(now, 0);
		recorder.searchText("p", now += 300);
		recorder.searchText("pr", now += 300);
		recorder.searchText("pray*", now += 300);
		take(PRAYER_4, "Prayer potion(4)", 0, 0, false);
		take(PRAYER_4, "Prayer potion(4)", 0, 0, false);
		recorder.endSearch(now += 500);
		take(SHARK, "Shark", 0, 2, false);
		recorder.close(now += 1000);

		Visit visit = journal.getVisits().get(0);
		assertEquals(1, visit.searches());
		List<Action> actions = visit.getActions();
		assertEquals(Action.Kind.SEARCH, actions.get(0).getKind());
		assertEquals("pray", actions.get(0).getQuery());
		assertTrue(actions.get(1).isSearched());
		assertTrue(actions.get(2).isSearched());
		assertFalse(actions.get(3).isSearched());
	}

	@Test
	public void quantityPromptsAreNotSearches()
	{
		recorder.open(now, 0);
		take(SHARK, "Shark", 0, 0, false);
		recorder.close(now += 1000);
		assertEquals(0, journal.getVisits().get(0).searches());
	}

	@Test
	public void idleBankSplitsTheVisit()
	{
		recorder.open(now, 0);
		take(SHARK, "Shark", 0, 0, false);
		now += Recorder.IDLE_MS + 1000;
		assertTrue(recorder.tick(now));
		take(WHIP, "Abyssal whip", 0, 0, false);
		recorder.close(now += 2000);
		assertEquals(2, journal.getVisits().size());
		assertTrue(journal.getVisits().get(1).gearUpMillis() < 5000);
	}

	@Test
	public void putBackOnlyCountsQuickReturns()
	{
		recorder.open(now, 0);
		take(SHARK, "Shark", 0, 0, false);
		recorder.deposit(SHARK, "Shark", now += 2000);
		take(WHIP, "Abyssal whip", 0, 0, false);
		recorder.deposit(WHIP, "Abyssal whip", now += 60_000);
		recorder.close(now += 1000);
		Visit visit = journal.getVisits().get(0);
		assertEquals(1, visit.putBackCount());
		assertEquals(Integer.valueOf(1), visit.putBacks().get(SHARK));
	}

	@Test
	public void frictionRisesWithHunting()
	{
		meleeTrip(false);
		meleeTrip(true);
		Visit calm = journal.getVisits().get(0);
		Visit hunted = journal.getVisits().get(1);
		assertTrue(hunted.friction() > calm.friction());
		assertTrue(calm.friction() >= 0 && hunted.friction() <= 100);
	}

	@Test
	public void sortsAdviceMostValuableFirstAndFindsTheLoadout()
	{
		for (int i = 0; i < 6; i++)
		{
			meleeTrip(true);
		}
		Report report = Analysis.of(journal);
		assertEquals(6, report.getTrips());
		assertTrue(report.getFriction() > 0);

		assertEquals(1, report.getLoadouts().size());
		Loadout loadout = report.getLoadouts().get(0);
		assertEquals(4, loadout.getItems().size());
		assertEquals("Abyssal whip & Avernic defender", loadout.getName());
		assertEquals(2, loadout.getTabs());

		List<Advice> advice = report.getAdvice();
		assertFalse(advice.isEmpty());
		for (int i = 1; i < advice.size(); i++)
		{
			assertTrue(advice.get(i - 1).impact() >= advice.get(i).impact());
		}
		assertTrue(has(advice, Advice.Kind.GATHER));
		assertTrue(has(advice, Advice.Kind.RAISE));
	}

	@Test
	public void twoLoadoutsStayApart()
	{
		for (int i = 0; i < 4; i++)
		{
			meleeTrip(false);
			recorder.open(now, 0);
			take(11785, "Armadyl crossbow", 0, 0, false);
			take(RUNE_POUCH, "Rune pouch", 0, 0, false);
			take(2444, "Ranging potion(4)", 0, 1, false);
			take(SHARK, "Shark", 0, 1, false);
			recorder.close(now += 2000);
			now += 600_000;
		}
		Report report = Analysis.of(journal);
		assertEquals(2, report.getLoadouts().size());
	}

	@Test
	public void repeatedSearchBecomesAdvice()
	{
		for (int i = 0; i < 3; i++)
		{
			recorder.open(now, 0);
			recorder.searchText("rune pouch", now += 500);
			take(RUNE_POUCH, "Rune pouch", 0, 0, false);
			recorder.close(now += 1000);
			now += 600_000;
		}
		Advice search = find(Analysis.of(journal).getAdvice(), Advice.Kind.SEARCH);
		assertNotNull(search);
		assertEquals(Arrays.asList(RUNE_POUCH), search.getItems());
	}

	@Test
	public void partialDosesSuggestDecanting()
	{
		for (int i = 0; i < 3; i++)
		{
			recorder.open(now, 0);
			take(PRAYER_4, "Prayer potion(4)", 0, 0, false);
			take(PRAYER_3, "Prayer potion(3)", 0, 0, false);
			recorder.close(now += 1000);
			now += 600_000;
		}
		Advice decant = find(Analysis.of(journal).getAdvice(), Advice.Kind.DECANT);
		assertNotNull(decant);
		assertEquals("Decant your Prayer potion", decant.getTitle());
	}

	@Test
	public void emptyJournalHasNoScore()
	{
		Report report = Analysis.of(journal);
		assertEquals(-1, report.getFriction());
		assertTrue(report.getAdvice().isEmpty());
	}

	@Test
	public void journalSurvivesASaveAndLoad()
	{
		meleeTrip(true);
		Gson gson = new Gson();
		Journal read = gson.fromJson(gson.toJson(journal), Journal.class).repair();
		assertEquals(1, read.getVisits().size());
		Visit visit = read.getVisits().get(0);
		assertEquals(4, visit.withdrawals());
		assertEquals(1, visit.tabSwitches());
		assertEquals("Shark", read.name(SHARK));
	}

	@Test
	public void trimForgetsOldVisitsAndTheirNames()
	{
		recorder.setKeep(1);
		recorder.open(now, 0);
		take(SHARK, "Shark", 0, 0, false);
		recorder.close(now += 1000);
		recorder.open(now, 0);
		take(WHIP, "Abyssal whip", 0, 0, false);
		recorder.close(now += 1000);
		assertEquals(1, journal.getVisits().size());
		assertFalse(journal.getNames().containsKey(SHARK));
	}

	@Test
	public void readsTheFirstVersionsHistory()
	{
		String old = "{\"sessions\":[{\"startMillis\":1000,\"endMillis\":9000,\"interactions\":["
			+ "{\"type\":\"WITHDRAW\",\"itemId\":4151,\"itemName\":\"Abyssal whip\",\"timeMillis\":2000},"
			+ "{\"type\":\"TAB_SWITCH\",\"itemId\":-1,\"itemName\":\"Bank tab\",\"timeMillis\":3000}]},"
			+ "{\"startMillis\":20000,\"endMillis\":21000,\"interactions\":[]}],"
			+ "\"searches\":[{\"query\":\"Whip\",\"timeMillis\":2500}],"
			+ "\"itemNames\":{\"4151\":\"Abyssal whip\"}}";
		Journal read = Legacy.read(old);
		assertNotNull(read);
		assertEquals(1, read.getVisits().size());
		Visit visit = read.getVisits().get(0);
		assertEquals(1, visit.withdrawals());
		assertEquals(1, visit.tabSwitches());
		assertEquals(1, visit.searches());
		assertEquals("Abyssal whip", read.name(WHIP));
		assertNull(Legacy.read("not json"));
		assertNull(Legacy.read(""));
	}

	private static boolean has(List<Advice> advice, Advice.Kind kind)
	{
		return find(advice, kind) != null;
	}

	private static Advice find(List<Advice> advice, Advice.Kind kind)
	{
		for (Advice a : advice)
		{
			if (a.getKind() == kind)
			{
				return a;
			}
		}
		return null;
	}
